window.PERSONA_EXPLAIN_DATA={"meta":{"translation":"개역한글","publisher":"대한성서공회","source":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN","note":"인물소개는 앱의 설명이며, 관련말씀은 공식 본문의 직접 인용입니다."},"byKey":{"C+L+M":{"intro":"바나바는 모두가 두려워하던 사울을 사도들에게 데려가 그가 겪은 일을 전했어요. 안디옥 교회에서는 사람들에게 주와 함께 머물러 있으라고 권했어요. 그 뒤 성령의 보내심을 받아 구브로의 회당들에서 하나님의 말씀을 전했어요.","main":[{"ref":"사도행전 9:27","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=act&chap=9&sec=1","verses":[{"n":27,"t":"바나바가 데리고 사도들에게 가서 그가 길에서 어떻게 주를 본 것과 주께서 그에게 말씀하신 일과 다메섹에서 그가 어떻게 예수의 이름으로 담대히 말하던 것을 말하니라"}]},{"ref":"사도행전 11:26","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=act&chap=11&sec=1","verses":[{"n":26,"t":"만나매 안디옥에 데리고 와서 둘이 교회에 일년간 모여 있어 큰 무리를 가르쳤고 제자들이 안디옥에서 비로소 그리스도인이라 일컬음을 받게 되었더라"}]}],"more":[{"ref":"사도행전 9:26","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=act&chap=9&sec=1","verses":[{"n":26,"t":"사울이 예루살렘에 가서 제자들을 사귀고자 하나 다 두려워하여 그의 제자 됨을 믿지 아니하니"}]},{"ref":"사도행전 11:25","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=act&chap=11&sec=1","verses":[{"n":25,"t":"바나바가 사울을 찾으러 다소에 가서"}]},{"ref":"사도행전 11:23","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=act&chap=11&sec=1","verses":[{"n":23,"t":"저가 이르러 하나님의 은혜를 보고 기뻐하여 모든 사람에게 굳은 마음으로 주께 붙어 있으라 권하니"}]},{"ref":"사도행전 13:4-5","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=act&chap=13&sec=1","verses":[{"n":4,"t":"두 사람이 성령의 보내심을 받아 실루기아에 내려가 거기서 배 타고 구브로에 가서"},{"n":5,"t":"살라미에 이르러 하나님의 말씀을 유대인의 여러 회당에서 전할쌔 요한을 수종자로 두었더라"}]}]},"C+L+P":{"intro":"느헤미야는 예루살렘 성벽이 무너졌다는 소식을 듣고 앉아서 울며 여러 날 금식하고 기도했어요. 예루살렘에 가서는 성을 다시 짓자고 사람들에게 말했어요. 사람들은 일어나 건축하자며 힘을 냈어요.","main":[{"ref":"느헤미야 1:4","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=neh&chap=1&sec=1","verses":[{"n":4,"t":"내가 이 말을 듣고 앉아서 울고 수일 동안 슬퍼하며 하늘의 하나님 앞에 금식하며 기도하여"}]},{"ref":"느헤미야 2:18","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=neh&chap=2&sec=1","verses":[{"n":18,"t":"또 저희에게 하나님의 선한 손이 나를 도우신 일과 왕이 내게 이른 말씀을 고하였더니 저희의 말이 일어나 건축하자 하고 모두 힘을 내어 이 선한 일을 하려 하매"}]}],"more":[{"ref":"느헤미야 1:3","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=neh&chap=1&sec=1","verses":[{"n":3,"t":"저희가 내게 이르되 사로잡힘을 면하고 남은 자가 그 도에서 큰 환난을 만나고 능욕을 받으며 예루살렘성은 훼파되고 성문들은 소화되었다 하는지라"}]},{"ref":"느헤미야 2:17","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=neh&chap=2&sec=1","verses":[{"n":17,"t":"후에 저희에게 이르기를 우리의 당한 곤경은 너희도 목도하는바라 예루살렘이 황무하고 성문이 소화되었으니 자, 예루살렘 성을 중건하여 다시 수치를 받지 말자 하고"}]},{"ref":"느헤미야 1:5-6","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=neh&chap=1&sec=1","verses":[{"n":5,"t":"가로되 하늘의 하나님 여호와 크고 두려우신 하나님이여 주를 사랑하고 주의 계명을 지키는 자에게 언약을 지키시며 긍휼을 베푸시는 주여 간구하나이다"},{"n":6,"t":"이제 종이 주의 종 이스라엘 자손을 위하여 주야로 기도하오며 이스라엘 자손의 주 앞에 범죄함을 자복하오니 주는 귀를 기울이시며 눈을 여시사 종의 기도를 들으시옵소서 나와 나의 아비 집이 범죄하여"}]},{"ref":"느헤미야 2:4","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=neh&chap=2&sec=1","verses":[{"n":4,"t":"왕이 내게 이르시되 그러면 네가 무엇을 원하느냐 하시기로 내가 곧 하늘의 하나님께 묵도하고"}]}]},"C+L+R":{"intro":"요나단은 블레셋 부대 앞에서 무기를 든 소년에게 건너편 부대로 건너가자고 먼저 말하고 앞장섰어요. 또 숨어 있던 다윗을 찾아가 하나님을 의지하도록 힘을 주었어요. 두려워하지 말라고 다윗에게 말해 주었어요.","main":[{"ref":"사무엘상 23:16","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=1sa&chap=23&sec=1","verses":[{"n":16,"t":"사울의 아들 요나단이 일어나 수풀에 들어가서 다윗에게 이르러 그로 하나님을 힘있게 의지하게 하였는데"}]},{"ref":"사무엘상 14:6","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=1sa&chap=14&sec=1","verses":[{"n":6,"t":"요나단이 자기 병기 든 소년에게 이르되 우리가 이 할례 없는 자들의 부대에게로 건너가자 여호와께서 우리를 위하여 일하실까 하노라 여호와의 구원은 사람의 많고 적음에 달리지 아니하였느니라"}]}],"more":[{"ref":"사무엘상 23:17","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=1sa&chap=23&sec=1","verses":[{"n":17,"t":"곧 요나단이 그에게 이르기를 두려워 말라 내 부친 사울의 손이 네게 미치지 못할 것이요 너는 이스라엘 왕이 되고 나는 네 다음이 될 것을 내 부친 사울도 안다 하니라"}]},{"ref":"사무엘상 14:7","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=1sa&chap=14&sec=1","verses":[{"n":7,"t":"병기 든 자가 그에게 이르되 당신의 마음에 있는대로 다 행하여 앞서 가소서 내가 당신과 마음을 같이하여 따르리이다"}]},{"ref":"사무엘상 14:1","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=1sa&chap=14&sec=1","verses":[{"n":1,"t":"하루는 사울의 아들 요나단이 자기 병기를 든 소년에게 이르되 우리가 건너편 블레셋 사람의 부대에게로 건너가자 하고 그 아비에게는 고하지 아니하였더라"}]},{"ref":"사무엘상 14:8-10","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=1sa&chap=14&sec=1","verses":[{"n":8,"t":"요나단이 가로되 보라 우리가 그 사람들에게로 건너가서 그들에게 보이리니"},{"n":9,"t":"그들이 만일 이같이 우리에게 이르기를 우리가 너희에게로 가기를 기다리라 하면 우리는 우리 곳에 가만히 서서 그들에게로 올라가지 말 것이요"},{"n":10,"t":"그들이 만일 이같이 말하기를 우리에게로 올라오라 하면 우리가 올라갈 것은 여호와께서 그들을 우리 손에 붙이셨음이니 이것이 우리에게 표징이 되리라 하고"}]}]},"C+L+S":{"intro":"보아스는 룻에게 다른 밭으로 가지 말라며 일꾼들에게 건드리지 말라고 일렀어요. 성문에 장로 열 명을 청해 모두 앞에서 일을 처리했어요. 룻에게 볶은 곡식을 주고 보리를 되어 지워 주었어요.","main":[{"ref":"룻기 2:8","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=rut&chap=2&sec=1","verses":[{"n":8,"t":"보아스가 룻에게 이르되 내 딸아 들으라 이삭을 주우러 다른 밭으로 가지 말며 여기서 떠나지 말고 나의 소녀들과 함께 있으라"}]},{"ref":"룻기 4:9","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=rut&chap=4&sec=1","verses":[{"n":9,"t":"보아스가 장로들과 모든 백성에게 이르되 내가 엘리멜렉과 기룐과 말론에게 있던 모든 것을 나오미의 손에서 산 일에 너희가 오늘날 증인이 되었고"}]}],"more":[{"ref":"룻기 2:9-12","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=rut&chap=2&sec=1","verses":[{"n":9,"t":"그들의 베는 밭을 보고 그들을 따르라 내가 그 소년들에게 명하여 너를 건드리지 말라 하였느니라 목이 마르거든 그릇에 가서 소년들의 길어 온 것을 마실찌니라"},{"n":10,"t":"룻이 땅에 엎드려 절하며 그에게 이르되 나는 이방 여인이어늘 당신이 어찌하여 내게 은혜를 베푸시며 나를 돌아보시나이까"},{"n":11,"t":"보아스가 그에게 대답하여 가로되 네 남편이 죽은 후로 네가 시모에게 행한 모든 것과 네 부모와 고국을 떠나 전에 알지 못하던 백성에게로 온 일이 내게 분명히 들렸느니라"},{"n":12,"t":"여호와께서 네 행한 일을 보응하시기를 원하며 이스라엘의 하나님 여호와께서 그 날개 아래 보호를 받으러 온 네게 온전한 상 주시기를 원하노라"}]},{"ref":"룻기 4:1-2","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=rut&chap=4&sec=1","verses":[{"n":1,"t":"보아스가 성문에 올라가서 거기 앉았더니 마침 보아스의 말하던 기업 무를 자가 지나는지라 보아스가 그에게 이르되 아무여 이리로 와서 앉으라 그가 와서 앉으매"},{"n":2,"t":"보아스가 성읍 장로 십인을 청하여 가로되 당신들은 여기 앉으라 그들이 앉으매"}]},{"ref":"룻기 4:10-11","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=rut&chap=4&sec=1","verses":[{"n":10,"t":"또 말론의 아내 모압 여인 룻을 사서 나의 아내로 취하고 그 죽은 자의 기업을 그 이름으로 잇게 하여 그 이름이 그 형제 중과 그곳 성문에서 끊어지지 않게 함에 너희가 오늘날 증인이 되었느니라"},{"n":11,"t":"성문에 있는 모든 백성과 장로들이 가로되 우리가 증인이 되노니 여호와께서 네 집에 들어가는 여인으로 이스라엘 집을 세운 라헬, 레아 두 사람과 같게 하시고 너로 에브랏에서 유력하고 베들레헴에서 유명케 하시기를 원하며"}]},{"ref":"룻기 3:15","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=rut&chap=3&sec=1","verses":[{"n":15,"t":"보아스가 가로되 네 겉옷을 가져다가 펴서 잡으라 펴서 잡으니 보리를 여섯번 되어 룻에게 이워주고 성으로 들어가니라"}]},{"ref":"룻기 2:14","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=rut&chap=2&sec=1","verses":[{"n":14,"t":"식사할 때에 보아스가 룻에게 이르되 이리로 와서 떡을 먹으며 네 떡 조각을 초에 찍으라 룻이 곡식 베는 자 곁에 앉으니 그가 볶은 곡식을 주매 룻이 배불리 먹고 남았더라"}]}]},"C+L+T":{"intro":"바울은 밀레도에서 에베소 교회 장로들을 불러 모았어요. 삼 년 동안 밤낮 눈물로 각 사람을 훈계하며 유익한 것을 가르쳤다고 말했어요. 그리고 장로들에게 교회를 보살피라고 맡겼어요.","main":[{"ref":"사도행전 20:28","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=act&chap=20&sec=1","verses":[{"n":28,"t":"너희는 자기를 위하여 또는 온 양떼를 위하여 삼가라 성령이 저들 가운데 너희로 감독자를 삼고 하나님이 자기 피로 사신 교회를 치게 하셨느니라"}]},{"ref":"사도행전 20:31","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=act&chap=20&sec=1","verses":[{"n":31,"t":"그러므로 너희가 일깨어 내가 삼년이나 밤낮 쉬지 않고 눈물로 각 사람을 훈계하던 것을 기억하라"}]}],"more":[{"ref":"사도행전 20:17","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=act&chap=20&sec=1","verses":[{"n":17,"t":"바울이 밀레도에서 사람을 에베소로 보내어 교회 장로들을 청하니"}]},{"ref":"사도행전 20:18","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=act&chap=20&sec=1","verses":[{"n":18,"t":"오매 저희에게 말하되 아시아에 들어온 첫날부터 지금까지 내가 항상 너희 가운데서 어떻게 행한 것을 너희도 아는바니"}]},{"ref":"사도행전 20:20","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=act&chap=20&sec=1","verses":[{"n":20,"t":"유익한 것은 무엇이든지 공중 앞에서나 각 집에서나 꺼림이 없이 너희에게 전하여 가르치고"}]}]},"C+L+W":{"intro":"드보라는 사사로서 사람들의 재판을 맡았고, 바락에게 전투를 준비하라고 말했어요. 전투 뒤에는 바락과 함께 하나님께 노래했어요.","main":[{"ref":"사사기 4:4","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=jdg&chap=4&sec=1","verses":[{"n":4,"t":"그 때에 랍비돗의 아내 여선지 드보라가 이스라엘의 사사가 되었는데"}]},{"ref":"사사기 5:1","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=jdg&chap=5&sec=1","verses":[{"n":1,"t":"이 날에 드보라와 아비노암의 아들 바락이 노래하여 가로되"}]}],"more":[{"ref":"사사기 4:5-9","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=jdg&chap=4&sec=1","verses":[{"n":5,"t":"그는 에브라임 산지 라마와 벧엘 사이 드보라의 종려나무 아래 거하였고 이스라엘 자손은 그에게 나아가 재판을 받더라"},{"n":6,"t":"드보라가 보내어 아비노암의 아들 바락을 납달리 게데스에서 불러다가 그에게 이르되 이스라엘 하나님 여호와께서 이같이 명하지 아니하셨느냐 이르시기를 너는 납달리 자손과 스불론 자손 일만명을 거느리고 다볼산으로 가라"},{"n":7,"t":"내가 야빈의 군대 장관 시스라와 그 병거들과 그 무리를 기손강으로 이끌어 네게 이르게 하고 그를 네 손에 붙이리라 하셨느니라"},{"n":8,"t":"바락이 그에게 이르되 당신이 나와 함께 가면 내가 가려니와 당신이 나와 함께 가지 아니하면 나는 가지 않겠노라"},{"n":9,"t":"가로되 내가 반드시 너와 함께 가리라 그러나 네가 이제 가는 일로는 영광을 얻지 못하리니 이는 여호와께서 시스라를 여인의 손에 파실것임이니라 하고 드보라가 일어나 바락과 함께 게데스로 가니라"}]},{"ref":"사사기 5:2-7","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=jdg&chap=5&sec=1","verses":[{"n":2,"t":"이스라엘의 두령이 그를 영솔하였고 백성이 즐거이 헌신하였으니 여호와를 찬송하라"},{"n":3,"t":"너희 왕들아 들으라 방백들아 귀를 기울이라 나 곧 내가 여호와를 노래할 것이요 이스라엘의 하나님 여호와를 찬송하리로다"},{"n":4,"t":"여호와여 주께서 세일에서부터 나오시고 에돔 들에서부터 진행하실 때에 땅이 진동하고 하늘도 새어서 구름이 물을 내렸나이다"},{"n":5,"t":"산들이 여호와 앞에서 진동하니 저 시내산도 이스라엘 하나님 여호와 앞에서 진동하였도다"},{"n":6,"t":"아낫의 아들 삼갈의 날에 또는 야엘의 날에는 대로가 비었고 행인들은 소로로 다녔도다"},{"n":7,"t":"이스라엘에 관원이 그치고 그쳤더니 나 드보라가 일어났고 내가 일어나서 이스라엘의 어미가 되었도다"}]}]},"C+M+P":{"intro":"고넬료는 집안 사람들과 함께 하나님을 경외하며 백성을 많이 구제하고 항상 기도했어요. 베드로를 청한 뒤에는 일가와 친구들을 모아 기다렸어요. 하나님이 명하신 모든 말씀을 듣고자 다 함께 모였어요.","main":[{"ref":"사도행전 10:2","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=act&chap=10&sec=1","verses":[{"n":2,"t":"그가 경건하여 온 집으로 더불어 하나님을 경외하며 백성을 많이 구제하고 하나님께 항상 기도하더니"}]},{"ref":"사도행전 10:33","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=act&chap=10&sec=1","verses":[{"n":33,"t":"내가 곧 당신에게 사람을 보내었더니 오셨으니 잘하였나이다 이제 우리는 주께서 당신에게 명하신 모든 것을 듣고자 하여 다 하나님 앞에 있나이다"}]}],"more":[{"ref":"사도행전 10:30","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=act&chap=10&sec=1","verses":[{"n":30,"t":"고넬료가 가로되 나흘 전 이맘때까지 내 집에서 제 구시 기도를 하는데 홀연히 한 사람이 빛난 옷을 입고 내 앞에 서서"}]},{"ref":"사도행전 10:24","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=act&chap=10&sec=1","verses":[{"n":24,"t":"이튿날 가이사랴에 들어가니 고넬료가 일가와 가까운 친구들을 모아 기다리더니"}]},{"ref":"사도행전 10:31","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=act&chap=10&sec=1","verses":[{"n":31,"t":"말하되 고넬료야 하나님이 네 기도를 들으시고 네 구제를 기억하셨으니"}]}]},"C+M+R":{"intro":"사람들이 중풍병자를 예수께 데려왔어요. 예수는 그에게 죄 사함을 말씀하시고, 사람들 앞에서 일어나 침상을 가지고 집으로 가라고 하셨어요.","main":[{"ref":"마가복음 2:5","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=mrk&chap=2&sec=1","verses":[{"n":5,"t":"예수께서 저희의 믿음을 보시고 중풍병자에게 이르시되 소자야 네 죄 사함을 받았느니라 하시니"}]},{"ref":"마가복음 2:11","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=mrk&chap=2&sec=1","verses":[{"n":11,"t":"내가 네게 이르노니 일어나 네 상을 가지고 집으로 가라 하시니"}]}],"more":[{"ref":"마가복음 2:3","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=mrk&chap=2&sec=1","verses":[{"n":3,"t":"사람들이 한 중풍병자를 네 사람에게 메워 가지고 예수께로 올쌔"}]},{"ref":"마가복음 2:4","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=mrk&chap=2&sec=1","verses":[{"n":4,"t":"무리를 인하여 예수께 데려갈 수 없으므로 그 계신 곳의 지붕을 뜯어 구멍을 내고 중풍병자의 누운 상을 달아내리니"}]},{"ref":"마가복음 2:6-10","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=mrk&chap=2&sec=1","verses":[{"n":6,"t":"어떤 서기관들이 거기 앉아서 마음에 의논하기를"},{"n":7,"t":"이 사람이 어찌 이렇게 말하는가 참람하도다 오직 하나님 한 분 외에는 누가 능히 죄를 사하겠느냐"},{"n":8,"t":"저희가 속으로 이렇게 의논하는 줄을 예수께서 곧 중심에 아시고 이르시되 어찌하여 이것을 마음에 의논하느냐"},{"n":9,"t":"중풍병자에게 네 죄 사함을 받았느니라 하는 말과 일어나 네 상을 가지고 걸어가라 하는 말이 어느 것이 쉽겠느냐"},{"n":10,"t":"그러나 인자가 땅에서 죄를 사하는 권세가 있는 줄을 너희로 알게 하려하노라 하시고 중풍병자에게 말씀하시되"}]},{"ref":"마가복음 2:12","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=mrk&chap=2&sec=1","verses":[{"n":12,"t":"그가 일어나 곧 상을 가지고 모든 사람 앞에서 나가거늘 저희가 다 놀라 영광을 하나님께 돌리며 가로되 우리가 이런 일을 도무지 보지 못하였다 하더라"}]}]},"C+M+S":{"intro":"도르가는 선행과 구제하는 일이 심히 많은 제자였어요. 과부들은 그가 함께 있을 때 지어 준 속옷과 겉옷을 베드로에게 내어 보였어요.","main":[{"ref":"사도행전 9:36","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=act&chap=9&sec=1","verses":[{"n":36,"t":"욥바에 다비다라 하는 여제자가 있으니 그 이름을 번역하면 도르가라 선행과 구제하는 일이 심히 많더니"}]},{"ref":"사도행전 9:39","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=act&chap=9&sec=1","verses":[{"n":39,"t":"베드로가 일어나 저희와 함께 가서 이르매 저희가 데리고 다락에 올라가니 모든 과부가 베드로의 곁에 서서 울며 도르가가 저희와 함께 있을 때에 지은 속옷과 겉옷을 다 내어 보이거늘"}]}],"more":[]},"C+M+T":{"intro":"바울은 디모데를 데살로니가 교회로 보내 믿음을 굳게 하고 위로하게 했어요. 디모데는 돌아와 그들의 믿음과 사랑의 기쁜 소식을 전했어요. 바울은 디모데를 신실한 아들이라 부르며 가는 곳마다 가르친 것을 생각나게 할 사람으로 보냈다고 했어요.","main":[{"ref":"데살로니가전서 3:2","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=1th&chap=3&sec=1","verses":[{"n":2,"t":"우리 형제 곧 그리스도 복음의 하나님의 일군인 디모데를 보내노니 이는 너희를 굳게 하고 너희 믿음에 대하여 위로함으로"}]},{"ref":"데살로니가전서 3:6","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=1th&chap=3&sec=1","verses":[{"n":6,"t":"지금은 디모데가 너희에게로부터 와서 너희 믿음과 사랑의 기쁜 소식을 우리에게 전하고 또 너희가 항상 우리를 잘 생각하여 우리가 너희를 간절히 보고자 함과 같이 너희도 우리를 간절히 보고자 한다 하니"}]}],"more":[{"ref":"고린도전서 4:17","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=1co&chap=4&sec=1","verses":[{"n":17,"t":"이를 인하여 내가 주 안에서 내 사랑하고 신실한 아들 디모데를 너희에게 보내었노니 저가 너희로 하여금 그리스도 예수 안에서 나의 행사 곧 내가 각처 각 교회에서 가르치는 것을 생각나게 하리라"}]}]},"C+M+W":{"intro":"실라는 예루살렘에서 정한 결정을 안디옥에 전하러 갔고, 말로 형제들을 권면하고 굳게 했어요. 빌립보 감옥에서는 바울과 함께 하나님을 찬송했어요.","main":[{"ref":"사도행전 15:32","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=act&chap=15&sec=1","verses":[{"n":32,"t":"유다와 실라도 선지자라 여러 말로 형제를 권면하여 굳게 하고"}]},{"ref":"사도행전 16:25","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=act&chap=16&sec=1","verses":[{"n":25,"t":"밤중쯤 되어 바울과 실라가 기도하고 하나님을 찬미하매 죄수들이 듣더라"}]}],"more":[{"ref":"사도행전 15:22","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=act&chap=15&sec=1","verses":[{"n":22,"t":"이에 사도와 장로와 온 교회가 그 중에서 사람을 택하여 바울과 바나바와 함께 안디옥으로 보내기를 가결하니 곧 형제 중에 인도자인 바사바라 하는 유다와 실라더라"}]},{"ref":"사도행전 15:27","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=act&chap=15&sec=1","verses":[{"n":27,"t":"그리하여 유다와 실라를 보내니 저희도 이 일을 말로 전하리라"}]}]},"C+P+R":{"intro":"예레미야는 유다를 위해 하나님께 간구했어요. 하나님의 지시에 따라 밭을 사고 매매 문서를 보관했어요. 그 뒤에도 하나님께 기도했어요.","main":[{"ref":"예레미야 32:9","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=jer&chap=32&sec=1","verses":[{"n":9,"t":"내 숙부의 아들 하나멜의 아나돗에 있는 밭을 사는데 은 십 칠세겔을 달아주되"}]},{"ref":"예레미야 32:17","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=jer&chap=32&sec=1","verses":[{"n":17,"t":"슬프도소이다 주 여호와여 주께서 큰 능과 드신 팔로 천지를 지으셨사오니 주에게는 능치 못한 일이 없으시니이다"}]}],"more":[{"ref":"예레미야 14:7","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=jer&chap=14&sec=1","verses":[{"n":7,"t":"여호와여 우리의 죄악이 우리에게 대하여 증거할찌라도 주는 주의 이름을 위하여 일하소서 우리의 타락함이 많으니이다 우리가 주께 범죄하였나이다"}]},{"ref":"예레미야 14:8-9","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=jer&chap=14&sec=1","verses":[{"n":8,"t":"이스라엘의 소망이시요 곤란한 때의 구원자시여 어찌하여 이 땅에서 거류하는 자 같이, 하룻밤을 유숙하는 행인 같이 하시나이까"},{"n":9,"t":"어찌하여 놀라 벙벙하는 자 같으시며 구원치 못하는 용사 같으시니이까 여호와여 주는 오히려 우리 중에 계시고 우리는 주의 이름으로 일컬음을 받는 자이오니 우리를 버리지 마옵소서"}]},{"ref":"예레미야 32:6-8","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=jer&chap=32&sec=1","verses":[{"n":6,"t":"예레미야가 가로되 여호와의 말씀이 내게 임하였느니라 이르시기를"},{"n":7,"t":"보라 네 숙부 살룸의 아들 하나멜이 네게 와서 말하기를 너는 아나돗에 있는 내 밭을 사라 이 기업을 무를 권리가 네게 있느니라 하리라 하시더니"},{"n":8,"t":"여호와의 말씀 같이 나의 숙부의 아들 하나멜이 시위대 뜰안 내게로 와서 이르되 청하노니 너는 베냐민 땅 아나돗에 있는 나의 밭을 사라 기업의 상속권이 네게 있고 무를 권리가 네게 있으니 너를 위하여 사라 하는지라 내가 이것이 여호와의 말씀인줄 알았으므로"}]},{"ref":"예레미야 32:10-15","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=jer&chap=32&sec=1","verses":[{"n":10,"t":"증서를 써서 인봉하고 증인을 세우고 은을 저울에 달아 주고"},{"n":11,"t":"법과 규례대로 인봉하고 인봉치 아니한 매매증서를 내가 취하여"},{"n":12,"t":"나의 숙부의 아들 하나멜과 매매증서에 인 친 증인의 앞과 시위대 뜰에 앉은 유다 모든 사람 앞에서 그 매매증서를 마세야의 손자 네리야의 아들 바룩에게 부치며"},{"n":13,"t":"그들의 앞에서 바룩에게 명하여 이르되"},{"n":14,"t":"만군의 여호와 이스라엘의 하나님이 이같이 말씀하시기를 너는 이 증서 곧 인봉하고 인봉치 않은 매매증서를 취하여 토기에 담아 많은 날 동안 보존케 하라"},{"n":15,"t":"만군의 여호와 이스라엘의 하나님 내가 이같이 말하노라 사람이 이 땅에서 집과 밭과 포도원을 다시 사게 되리라 하셨다 하니라"}]},{"ref":"예레미야 32:16","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=jer&chap=32&sec=1","verses":[{"n":16,"t":"내가 매매증서를 네리야의 아들 바룩에게 부친 후에 여호와께 기도하여 가로되"}]},{"ref":"예레미야 32:18-25","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=jer&chap=32&sec=1","verses":[{"n":18,"t":"주는 은혜를 천만인에게 베푸시며 아비의 죄악을 그 후 자손의 품에 갚으시오니 크고 능하신 하나님이시요 이름은 만군의 여호와시니이다"},{"n":19,"t":"주는 모략에 크시며 행사에 능하시며 인류의 모든 길에 주목하시며 그 길과 그 행위의 열매대로 보응하시나이다"},{"n":20,"t":"주께서 애굽 땅에서 징조와 기사로 행하셨고 오늘까지도 이스라엘과 외인 중에 그 같이 행하사 주의 이름을 오늘과 같이 되게 하셨나이다"},{"n":21,"t":"주께서 징조와 기사와 강한 손과 드신 팔과 큰 두려움으로 주의 백성 이스라엘을 애굽 땅에서 인도하여 내시고"},{"n":22,"t":"그들에게 주시기로 그 열조에게 맹세하신바 젖과 꿀이 흐르는 이 땅을 그들에게 주셨으므로"},{"n":23,"t":"그들이 들어가서 이를 차지하였거늘 주의 목소리를 청종치 아니하며 주의 도에 행치 아니하며 무릇 주께서 행하라 명하신 일을 행치 아니하였으므로 주께서 이 모든 재앙을 그들에게 내리셨나이다"},{"n":24,"t":"보옵소서 이 성을 취하려 하는 자가 와서 흉벽을 쌓았고 칼과 기근과 염병으로 인하여 이 성이 이를 치는 갈대아인의 손에 붙인바 되었으니 주의 말씀대로 되었음을 주께서 보시나이다"},{"n":25,"t":"주 여호와여 주께서 내게 은으로 밭을 사며 증인을 세우라 하셨으나 이 성은 갈대아인의 손에 붙인바 되었나이다"}]}]},"C+P+S":{"intro":"욥은 지난날 고아와 가난한 사람을 건지고 어려운 이웃을 도왔다고 돌아보았어요. 뒤에는 자신을 찾아온 친구들을 위해 기도했어요.","main":[{"ref":"욥기 29:12","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=job&chap=29&sec=1","verses":[{"n":12,"t":"이는 내가 부르짖는 빈민과 도와줄 자 없는 고아를 건졌음이라"}]},{"ref":"욥기 42:10","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=job&chap=42&sec=1","verses":[{"n":10,"t":"욥이 그 벗들을 위하여 빌매 여호와께서 욥의 곤경을 돌이키시고 욥에게 그전 소유보다 갑절이나 주신지라"}]}],"more":[{"ref":"욥기 29:13-17","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=job&chap=29&sec=1","verses":[{"n":13,"t":"망하게 된 자도 나를 위하여 복을 빌었으며 과부의 마음이 나로 인하여 기뻐 노래하였었느니라"},{"n":14,"t":"내가 의로 옷을 삼아 입었으며 나의 공의는 도포와 면류관 같았었느니라"},{"n":15,"t":"나는 소경의 눈도 되고 절뚝발이의 발도 되고"},{"n":16,"t":"빈궁한 자의 아비도 되며 생소한 자의 일을 사실하여 주었으며"},{"n":17,"t":"불의한 자의 어금니를 꺾고 그 잇사이에서 겁탈한 물건을 빼어 내었었느니라"}]},{"ref":"욥기 42:8-9","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=job&chap=42&sec=1","verses":[{"n":8,"t":"그런즉 너희는 수송아지 일곱과 수양 일곱을 취하여 내 종 욥에게 가서 너희를 위하여 번제를 드리라 내 종 욥이 너희를 위하여 기도할 것인즉 내가 그를 기쁘게 받으리니 너희의 우매한대로 너희에게 갚지 아니하리라 이는 너희가 나를 가리켜 말한 것이 내 종 욥의 말 같이 정당하지 못함이니라"},{"n":9,"t":"이에 데만 사람 엘리바스와 수아 사람 빌닷과 나아마 사람 소발이 가서 여호와께서 자기들에게 명하신대로 행하니라 여호와께서 욥을 기쁘게 받으셨더라"}]}]},"C+P+T":{"intro":"백성이 죽을까 두려워하며 사무엘에게 기도해 달라고 하자, 사무엘은 두려워하지 말라고 했어요. 그는 백성을 위해 기도하기를 쉬지 않겠다고 말했어요. 선하고 의로운 길을 가르치겠다고도 했어요.","main":[{"ref":"사무엘상 12:23","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=1sa&chap=12&sec=1","verses":[{"n":23,"t":"나는 너희를 위하여 기도하기를 쉬는 죄를 여호와 앞에 결단코 범치 아니하고 선하고 의로운 도로 너희를 가르칠 것인즉"}]}],"more":[{"ref":"사무엘상 12:19","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=1sa&chap=12&sec=1","verses":[{"n":19,"t":"모든 백성이 사무엘에게 이르되 당신의 종들을 위하여 당신의 하나님 여호와께 기도하여 우리로 죽지 않게 하소서 우리가 우리의 모든 죄에 왕을 구하는 악을 더하였나이다"}]},{"ref":"사무엘상 12:18","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=1sa&chap=12&sec=1","verses":[{"n":18,"t":"이에 사무엘이 여호와께 아뢰매 여호와께서 그 날에 우뢰와 비를 보내시니 모든 백성이 여호와와 사무엘을 크게 두려워하니라"}]},{"ref":"사무엘상 12:20","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=1sa&chap=12&sec=1","verses":[{"n":20,"t":"사무엘이 백성에게 이르되 두려워 말라 너희가 과연 이 모든 악을 행하였으나 여호와를 좇는 데서 돌이키지 말고 오직 너희 마음을 다하여 여호와를 섬기라"}]},{"ref":"사무엘상 12:24","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=1sa&chap=12&sec=1","verses":[{"n":24,"t":"너희는 여호와께서 너희를 위하여 행하신 그 큰 일을 생각하여 오직 그를 경외하며 너희의 마음을 다하여 진실히 섬기라"}]}]},"C+P+W":{"intro":"마리아는 혼인 잔치에서 포도주가 떨어진 것을 예수께 알렸어요. 하인들에게는 예수가 하시는 말씀대로 하라고 했어요. 사도들과 함께 오로지 기도에 힘썼고, 하나님을 찬양하는 노래를 불렀어요.","main":[{"ref":"요한복음 2:3","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=jhn&chap=2&sec=1","verses":[{"n":3,"t":"포도주가 모자란지라 예수의 어머니가 예수에게 이르되 저희에게 포도주가 없다 하니"}]},{"ref":"사도행전 1:14","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=act&chap=1&sec=1","verses":[{"n":14,"t":"여자들과 예수의 모친 마리아와 예수의 아우들로 더불어 마음을 같이하여 전혀 기도에 힘쓰니라"}]}],"more":[{"ref":"요한복음 2:4-5","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=jhn&chap=2&sec=1","verses":[{"n":4,"t":"예수께서 가라사대 여자여 나와 무슨 상관이 있나이까 내 때가 아직 이르지 못하였나이다"},{"n":5,"t":"그 어머니가 하인들에게 이르되 너희에게 무슨 말씀을 하시든지 그대로 하라 하니라"}]},{"ref":"누가복음 2:19","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=luk&chap=2&sec=1","verses":[{"n":19,"t":"마리아는 이 모든 말을 마음에 지키어 생각하니라"}]},{"ref":"누가복음 1:46-55","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=luk&chap=1&sec=1","verses":[{"n":46,"t":"마리아가 가로되 내 영혼이 주를 찬양하며"},{"n":47,"t":"내 마음이 하나님 내 구주를 기뻐하였음은"},{"n":48,"t":"그 계집종의 비천함을 돌아 보셨음이라 보라 이제 후로는 만세에 나를 복이 있다 일컬으리로다"},{"n":49,"t":"능하신 이가 큰 일을 내게 행하셨으니 그 이름이 거룩하시며"},{"n":50,"t":"긍휼하심이 두려워하는 자에게 대대로 이르는도다"},{"n":51,"t":"그의 팔로 힘을 보이사 마음의 생각이 교만한 자들을 흩으셨고"},{"n":52,"t":"권세 있는 자를 그 위에서 내리치셨으며 비천한 자를 높이셨고"},{"n":53,"t":"주리는 자를 좋은 것으로 배불리셨으며 부자를 공수로 보내셨도다"},{"n":54,"t":"그 종 이스라엘을 도우사 긍휼히 여기시고 기억하시되"},{"n":55,"t":"우리 조상에게 말씀하신 것과 같이 아브라함과 및 그 자손에게 영원히 하시리로다 하니라"}]}]},"C+R+S":{"intro":"엘리사는 수넴 여인의 집에 지날 때마다 들러 음식을 먹었어요. 여인은 그를 위해 담 위에 작은 방을 지었어요. 그 여인의 아들이 죽자 엘리사는 여호와께 기도하고 아이를 살려 어머니에게 돌려주었어요.","main":[{"ref":"열왕기하 4:8","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=2ki&chap=4&sec=1","verses":[{"n":8,"t":"하루는 엘리사가 수넴에 이르렀더니 거기 한 귀한 여인이 저를 간권하여 음식을 먹게 한고로 엘리사가 그곳을 지날 때마다 음식을 먹으러 그리로 들어갔더라"}]},{"ref":"열왕기하 4:33","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=2ki&chap=4&sec=1","verses":[{"n":33,"t":"들어가서는 문을 닫으니 두 사람 뿐이라 엘리사가 여호와께 기도하고"}]}],"more":[{"ref":"열왕기하 4:32","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=2ki&chap=4&sec=1","verses":[{"n":32,"t":"엘리사가 집에 들어가 보니 아이가 죽었는데 자기의 침상에 눕혔는지라"}]},{"ref":"열왕기하 4:34-35","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=2ki&chap=4&sec=1","verses":[{"n":34,"t":"아이의 위에 올라 엎드려 자기 입을 그 입에, 자기 눈을 그 눈에, 자기 손을 그 손에 대고 그 몸에 엎드리니 아이의 살이 차차 따뜻하더라"},{"n":35,"t":"엘리사가 내려서 집 안에서 한번 이리 저리 다니고 다시 아이 위에 올라 엎드리니 아이가 일곱번 재채기 하고 눈을 뜨는지라"}]},{"ref":"열왕기하 4:9-10","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=2ki&chap=4&sec=1","verses":[{"n":9,"t":"여인이 그 남편에게 이르되 항상 우리에게로 지나는 이 사람은 하나님의 거룩한 사람인줄을 내가 아노니"},{"n":10,"t":"우리가 저를 위하여 작은 방을 담 위에 짓고 침상과 책상과 의자와 촛대를 진설하사이다 저가 우리에게 이르면 거기 유하리이다 하였더라"}]}]},"C+R+T":{"intro":"이드로는 모세가 아침부터 저녁까지 혼자 재판하는 것을 보고 걱정했어요. 천부장, 백부장, 오십부장, 십부장을 세워 일을 나누는 방법을 일러 주었어요. 모세는 그의 말을 듣고 그대로 했어요.","main":[{"ref":"출애굽기 18:21","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=exo&chap=18&sec=1","verses":[{"n":21,"t":"그대는 또 온 백성 가운데서 재덕이 겸전한 자 곧 하나님을 두려워하며 진실무망하며 불의한 이를 미워하는 자를 빼서 백성 위에 세워 천부장과 백부장과 오십부장과 십부장을 삼아"}]},{"ref":"출애굽기 18:24","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=exo&chap=18&sec=1","verses":[{"n":24,"t":"이에 모세가 자기 장인의 말을 듣고 그 모든 말대로 하여"}]}],"more":[{"ref":"출애굽기 18:17","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=exo&chap=18&sec=1","verses":[{"n":17,"t":"모세의 장인이 그에게 이르되 그대의 하는 것이 선하지 못하도다"}]},{"ref":"출애굽기 18:18","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=exo&chap=18&sec=1","verses":[{"n":18,"t":"그대와 그대와 함께한 이 백성이 필연 기력이 쇠하리니 이 일이 그대에게 너무 중함이라 그대가 혼자 할 수 없으리라"}]},{"ref":"출애굽기 18:22-23","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=exo&chap=18&sec=1","verses":[{"n":22,"t":"그들로 때를 따라 백성을 재판하게 하라 무릇 큰 일이면 그대에게 베풀 것이고 무릇 작은 일이면 그들이 스스로 재판할 것이니 그리하면 그들이 그대와 함께 담당할 것인즉 일이 그대에게 쉬우리라"},{"n":23,"t":"그대가 만일 이 일을 하고 하나님께서도 그대에게 인가하시면 그대가 이 일을 감당하고 이 모든 백성도 자기 곳으로 평안히 가리라"}]},{"ref":"출애굽기 18:19-20","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=exo&chap=18&sec=1","verses":[{"n":19,"t":"이제 내 말을 들으라 내가 그대에게 방침을 가르치리니 하나님이 그대와 함께 계실찌로다 그대는 백성을 위하여 하나님 앞에 있어서 소송을 하나님께 베풀며"},{"n":20,"t":"그들에게 율례와 법도를 가르쳐서 마땅히 갈 길과 할 일을 그들에게 보이고"}]}]},"C+R+W":{"intro":"미리암은 갈대 상자에 담긴 아기 모세가 어떻게 되는지 멀리서 지켜보았어요. 바로의 딸에게 히브리 유모를 불러오겠다고 하여 아기의 어머니를 데려왔어요. 홍해를 건넌 뒤에는 소고를 잡고 춤추며 여호와를 노래했어요.","main":[{"ref":"출애굽기 2:7","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=exo&chap=2&sec=1","verses":[{"n":7,"t":"그 누이가 바로의 딸에게 이르되 내가 가서 히브리 여인 중에서 유모를 불러다가 당신을 위하여 이 아이를 젖 먹이게 하리이까"}]},{"ref":"출애굽기 15:20","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=exo&chap=15&sec=1","verses":[{"n":20,"t":"아론의 누이 선지자 미리암이 손에 소고를 잡으매 모든 여인도 그를 따라 나오며 소고를 잡고 춤추니"}]}],"more":[{"ref":"출애굽기 2:4","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=exo&chap=2&sec=1","verses":[{"n":4,"t":"그 누이가 어떻게 되는 것을 알려고 멀리 섰더니"}]},{"ref":"출애굽기 2:8","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=exo&chap=2&sec=1","verses":[{"n":8,"t":"바로의 딸이 그에게 이르되 가라 그 소녀가 가서 아이의 어미를 불러오니"}]},{"ref":"출애굽기 15:21","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=exo&chap=15&sec=1","verses":[{"n":21,"t":"미리암이 그들에게 화답하여 가로되 너희는 여호와를 찬송하라 그는 높고 영화로우심이요 말과 그 탄 자를 바다에 던지셨음이로다 하였더라"}]}]},"C+S+T":{"intro":"브리스길라는 남편 아굴라와 함께 바울과 같은 천막 일을 하며 함께 지냈어요. 바울을 위해 목이라도 내어놓았다고 바울이 감사했어요. 아볼로에게는 하나님의 도를 더 자세히 풀어 일러 주었어요.","main":[{"ref":"사도행전 18:26","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=act&chap=18&sec=1","verses":[{"n":26,"t":"그가 회당에서 담대히 말하기를 시작하거늘 브리스길라와 아굴라가 듣고 데려다가 하나님의 도를 더 자세히 풀어 이르더라"}]},{"ref":"로마서 16:3","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=rom&chap=16&sec=1","verses":[{"n":3,"t":"너희가 그리스도 예수 안에서 나의 동역자들인 브리스가와 아굴라에게 문안하라"}]}],"more":[{"ref":"사도행전 18:2","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=act&chap=18&sec=1","verses":[{"n":2,"t":"아굴라라 하는 본도에서 난 유대인 하나를 만나니 글라우디오가 모든 유대인을 명하여 로마에서 떠나라 한고로 그가 그 아내 브리스길라와 함께 이달리야로부터 새로 온지라 바울이 그들에게 가매"}]},{"ref":"로마서 16:4","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=rom&chap=16&sec=1","verses":[{"n":4,"t":"저희는 내 목숨을 위하여 자기의 목이라도 내어놓았나니 나 뿐아니라 이방인의 모든 교회도 저희에게 감사하느니라"}]},{"ref":"사도행전 18:3","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=act&chap=18&sec=1","verses":[{"n":3,"t":"업이 같으므로 함께 거하여 일을 하니 그 업은 장막을 만드는 것이더라"}]},{"ref":"고린도전서 16:19","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=1co&chap=16&sec=1","verses":[{"n":19,"t":"아시아의 교회들이 너희에게 문안하고 아굴라와 브리스가와 및 그 집에 있는 교회가 주 안에서 너희에게 간절히 문안하고"}]}]},"C+S+W":{"intro":"마르다는 예수를 자기 집으로 영접했어요. 예수를 위한 잔치에서도 일을 맡아 섬겼어요. 마르다와 마리아는 오라버니가 병들었을 때 예수께 사람을 보내 알렸어요.","main":[{"ref":"누가복음 10:38","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=luk&chap=10&sec=1","verses":[{"n":38,"t":"저희가 길 갈 때에 예수께서 한 촌에 들어가시매 마르다라 이름하는 한 여자가 자기 집으로 영접하더라"}]},{"ref":"요한복음 12:2","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=jhn&chap=12&sec=1","verses":[{"n":2,"t":"거기서 예수를 위하여 잔치할쌔 마르다는 일을 보고 나사로는 예수와 함께 앉은자 중에 있더라"}]}],"more":[{"ref":"요한복음 11:3","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=jhn&chap=11&sec=1","verses":[{"n":3,"t":"이에 그 누이들이 예수께 사람을 보내어 가로되 주여 보시옵소서 사랑하시는 자가 병들었나이다 하니"}]},{"ref":"누가복음 10:39-40","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=luk&chap=10&sec=1","verses":[{"n":39,"t":"그에게 마리아라 하는 동생이 있어 주의 발아래 앉아 그의 말씀을 듣더니"},{"n":40,"t":"마르다는 준비하는 일이 많아 마음이 분주한지라 예수께 나아가 가로되 주여 내 동생이 나 혼자 일하게 두는 것을 생각지 아니하시나이까 저를 명하사 나를 도와주라 하소서"}]},{"ref":"요한복음 12:3","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=jhn&chap=12&sec=1","verses":[{"n":3,"t":"마리아는 지극히 비싼 향유 곧 순전한 나드 한 근을 가져다가 예수의 발에 붓고 자기 머리털로 그의 발을 씻으니 향유 냄새가 집에 가득하더라"}]}]},"C+T+W":{"intro":"느헤미야 시대에 레위 사람 예수아는 백성이 율법을 깨닫도록 도왔어요. 백성이 율법의 말씀을 듣고 울자 모든 백성을 조용하게 했어요. 그날은 거룩한 날이니 슬퍼하지 말라고 말했어요.","main":[{"ref":"느헤미야 8:7","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=neh&chap=8&sec=1","verses":[{"n":7,"t":"예수아와 바니와 세레뱌와 야민과 악굽과 사브대와 호디야와 마아세야와 그리다와 아사랴와 요사밧과 하난과 블라야와 레위 사람들이 다 그 처소에 섰는 백성에게 율법을 깨닫게 하는데"}]},{"ref":"느헤미야 8:11","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=neh&chap=8&sec=1","verses":[{"n":11,"t":"레위 사람들도 모든 백성을 정숙케 하여 이르기를 오늘은 성일이니 마땅히 종용하고 근심하지 말라 하매"}]}],"more":[{"ref":"느헤미야 8:8-10","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=neh&chap=8&sec=1","verses":[{"n":8,"t":"하나님의 율법 책을 낭독하고 그 뜻을 해석하여 백성으로 그 낭독하는 것을 다 깨닫게 하매"},{"n":9,"t":"백성이 율법의 말씀을 듣고 다 우는지라 총독 느헤미야와 제사장겸 학사 에스라와 백성을 가르치는 레위 사람들이 모든 백성에게 이르기를 오늘은 너희 하나님 여호와의 성일이니 슬퍼하지 말며 울지 말라 하고"},{"n":10,"t":"느헤미야가 또 이르기를 너희는 가서 살진 것을 먹고 단 것을 마시되 예비치 못한 자에게는 너희가 나누어 주라 이 날은 우리 주의 성일이니 근심하지 말라 여호와를 기뻐하는 것이 너희의 힘이니라 하고"}]}]},"L+M+P":{"intro":"세례 요한은 요단 부근에서 죄 사함을 받게 하는 회개의 세례를 전파했어요. 무리와 세리와 군인들에게 어떻게 할지 일러 주며 권면했어요. 제자들이 기도를 가르쳐 달라고 한 것은 요한이 자기 제자들에게 기도를 가르쳤기 때문이었어요.","main":[{"ref":"누가복음 3:3","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=luk&chap=3&sec=1","verses":[{"n":3,"t":"요한이 요단강 부근 각처에 와서 죄 사함을 얻게 하는 회개의 세례를 전파하니"}]},{"ref":"누가복음 11:1","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=luk&chap=11&sec=1","verses":[{"n":1,"t":"예수께서 한 곳에서 기도하시고 마치시매 제자 중 하나가 여짜오되 주여 요한이 자기 제자들에게 기도를 가르친 것과 같이 우리에게도 가르쳐 주옵소서"}]}],"more":[{"ref":"누가복음 3:4-18","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=luk&chap=3&sec=1","verses":[{"n":4,"t":"선지자 이사야의 책에 쓴바 광야에 외치는 자의 소리가 있어 가로되 너희는 주의 길을 예비하라 그의 첩경을 평탄케 하라"},{"n":5,"t":"모든 골짜기가 메워지고 모든 산과 작은 산이 낮아지고 굽은 것이 곧아지고 험한 길이 평탄하여질 것이요"},{"n":6,"t":"모든 육체가 하나님의 구원하심을 보리라 함과 같으니라"},{"n":7,"t":"요한이 세례 받으러 나오는 무리에게 이르되 독사의 자식들아 누가 너희를 가르쳐 장차 올 진노를 피하라 하더냐"},{"n":8,"t":"그러므로 회개에 합당한 열매를 맺고 속으로 아브라함이 우리 조상이라 말하지 말라 내가 너희에게 이르노니 하나님이 능히 이 돌들로도 아브라함의 자손이 되게 하시리라"},{"n":9,"t":"이미 도끼가 나무 뿌리에 놓였으니 좋은 열매 맺지 아니하는 나무마다 찍혀 불에 던지우리라"},{"n":10,"t":"무리가 물어 가로되 그러하면 우리가 무엇을 하리이까"},{"n":11,"t":"대답하여 가로되 옷 두 벌 있는 자는 옷 없는 자에게 나눠줄 것이요 먹을 것이 있는 자도 그렇게 할것이니라 하고"},{"n":12,"t":"세리들도 세례를 받고자하여 와서 가로되 선생이여 우리는 무엇을 하리이까 하매"},{"n":13,"t":"가로되 정한 세 외에는 늑징치 말라하고"},{"n":14,"t":"군병들도 물어 가로되 우리는 무엇을 하리이까 하매 가로되 사람에게 강포하지 말며 무소하지 말고 받는 요를 족한 줄로 알라 하니라"},{"n":15,"t":"백성들이 바라고 기다리므로 모든 사람들이 요한을 혹 그리스도신가 심중에 의논하니"},{"n":16,"t":"요한이 모든 사람에게 대답하여 가로되 나는 물로 너희에게 세례를 주거니와 나보다 능력이 많으신 이가 오시나니 나는 그 신들메를 풀기도 감당치 못하겠노라 그는 성령과 불로 너희에게 세례를 주실 것이요"},{"n":17,"t":"손에 키를 들고 자기의 타작마당을 정하게 하사 알곡은 모아 곡간에 들이고 쭉정이는 꺼지지 않는 불에 태우시리라"},{"n":18,"t":"또 기타 여러가지로 권하여 백성에게 좋은 소식을 전하였으나"}]}]},"L+M+R":{"intro":"예루살렘 회의에서 야고보는 내 말을 들으라며 말을 시작했어요. 하나님께로 돌아오는 이방인들을 괴롭게 하지 말자고 했어요. 그러면서 몇 가지만 멀리하도록 편지로 알리자고 제안했어요.","main":[{"ref":"사도행전 15:13","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=act&chap=15&sec=1","verses":[{"n":13,"t":"말을 마치매 야고보가 대답하여 가로되 형제들아 내 말을 들으라"}]},{"ref":"사도행전 15:19","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=act&chap=15&sec=1","verses":[{"n":19,"t":"그러므로 내 의견에는 이방인 중에서 하나님께로 돌아 오는 자들을 괴롭게 말고"}]}],"more":[{"ref":"사도행전 15:14-18","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=act&chap=15&sec=1","verses":[{"n":14,"t":"하나님이 처음으로 이방인 중에서 자기 이름을 위할 백성을 취하시려고 저희를 권고하신 것을 시므온이 고하였으니"},{"n":15,"t":"선지자들의 말씀이 이와 합하도다 기록된바"},{"n":16,"t":"이 후에 내가 돌아와서 다윗의 무너진 장막을 다시 지으며 또 그 퇴락한 것을 다시 지어 일으키리니"},{"n":17,"t":"이는 그 남은 사람들과 내 이름으로 일컬음을 받는 모든 이방인들로 주를 찾게 하려 함이라 하셨으니"},{"n":18,"t":"즉 예로부터 이것을 알게 하시는 주의 말씀이라 함과 같으니라"}]},{"ref":"사도행전 15:20","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=act&chap=15&sec=1","verses":[{"n":20,"t":"다만 우상의 더러운 것과 음행과 목매어 죽인 것과 피를 멀리 하라고 편지하는 것이 가하니"}]}]},"L+M+S":{"intro":"디도는 바울의 지시로 그레데에 남아 남은 일을 정리하고 장로를 세우는 일을 맡았어요. 고린도 교회에서 연보를 시작하는 일을 이어 맡았고, 그 일을 자원하여 나섰어요.","main":[{"ref":"디도서 1:5","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=tit&chap=1&sec=1","verses":[{"n":5,"t":"내가 너를 그레데에 떨어뜨려 둔 이유는 부족한 일을 바로잡고 나의 명한대로 각 성에 장로들을 세우게 하려 함이니"}]},{"ref":"고린도후서 8:17","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=2co&chap=8&sec=1","verses":[{"n":17,"t":"저가 권함을 받고 더욱 간절함으로 자원하여 너희에게 나아갔고"}]}],"more":[{"ref":"고린도후서 8:6","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=2co&chap=8&sec=1","verses":[{"n":6,"t":"이러므로 우리가 디도를 권하여 너희 가운데서 시작하였은즉 이 은혜를 그대로 성취케 하라 하였노라"}]},{"ref":"고린도후서 8:16","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=2co&chap=8&sec=1","verses":[{"n":16,"t":"너희를 위하여 같은 간절함을 디도의 마음에도 주시는 하나님께 감사하노니"}]},{"ref":"고린도후서 8:23","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=2co&chap=8&sec=1","verses":[{"n":23,"t":"디도로 말하면 나의 동무요 너희를 위한 나의 동역자요 우리 형제들로 말하면 여러 교회의 사자들이요 그리스도의 영광이니라"}]}]},"L+M+T":{"intro":"오순절에 베드로는 열한 사도와 함께 서서 소리를 높여 말했어요. 요엘과 다윗의 말을 풀어 예수가 누구신지 설명했어요. 마음에 찔린 사람들에게 회개하고 세례를 받으라고 권했고, 그날 삼천 명쯤이 더해졌어요.","main":[{"ref":"사도행전 2:14","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=act&chap=2&sec=1","verses":[{"n":14,"t":"베드로가 열 한 사도와 같이 서서 소리를 높여 가로되 유대인들과 예루살렘에 사는 모든 사람들아 이 일을 너희로 알게 할 것이니 내 말에 귀를 기울이라"}]},{"ref":"사도행전 2:38","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=act&chap=2&sec=1","verses":[{"n":38,"t":"베드로가 가로되 너희가 회개하여 각각 예수 그리스도의 이름으로 세례를 받고 죄 사함을 얻으라 그리하면 성령을 선물로 받으리니"}]}],"more":[{"ref":"사도행전 2:39-41","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=act&chap=2&sec=1","verses":[{"n":39,"t":"이 약속은 너희와 너희 자녀와 모든 먼데 사람 곧 주 우리 하나님이 얼마든지 부르시는 자들에게 하신 것이라 하고"},{"n":40,"t":"또 여러 말로 확증하며 권하여 가로되 너희가 이 패역한 세대에서 구원을 받으라 하니"},{"n":41,"t":"그 말을 받는 사람들은 세례를 받으매 이 날에 제자의 수가 삼천이나 더하더라"}]},{"ref":"사도행전 2:16-36","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=act&chap=2&sec=1","verses":[{"n":16,"t":"이는 곧 선지자 요엘로 말씀하신 것이니 일렀으되"},{"n":17,"t":"하나님이 가라사대 말세에 내가 내 영으로 모든 육체에게 부어 주리니 너희의 자녀들은 예언할 것이요 너희의 젊은이들은 환상을 보고 너희의 늙은이들은 꿈을 꾸리라"},{"n":18,"t":"그 때에 내가 내 영으로 내 남종과 여종들에게 부어 주리니 저희가 예언할 것이요"},{"n":19,"t":"또 내가 위로 하늘에서는 기사와 아래로 땅에서는 징조를 베풀리니 곧 피와 불과 연기로다"},{"n":20,"t":"주의 크고 영화로운 날이 이르기 전에 해가 변하여 어두워지고 달이 변하여 피가 되리라"},{"n":21,"t":"누구든지 주의 이름을 부르는 자는 구원을 얻으리라 하였느니라"},{"n":22,"t":"이스라엘 사람들아 이 말을 들으라 너희도 아는바에 하나님께서 나사렛 예수로 큰 권능과 기사와 표적을 너희 가운데서 베푸사 너희 앞에서 그를 증거하셨느니라"},{"n":23,"t":"그가 하나님의 정하신 뜻과 미리 아신대로 내어준바 되었거늘 너희가 법 없는 자들의 손을 빌어 못 박아 죽였으나"},{"n":24,"t":"하나님께서 사망의 고통을 풀어 살리셨으니 이는 그가 사망에게 매여 있을 수 없었음이라"},{"n":25,"t":"다윗이 저를 가리켜 가로되 내가 항상 내 앞에 계신 주를 뵈웠음이여 나로 요동치 않게 하기 위하여 그가 내 우편에 계시도다"},{"n":26,"t":"이러므로 내 마음이 기뻐하였고 내 입술도 즐거워하였으며 육체는 희망에 거하리니"},{"n":27,"t":"이는 내 영혼을 음부에 버리지 아니하시며 주의 거룩한 자로 썩음을 당치 않게 하실 것임이로다"},{"n":28,"t":"주께서 생명의 길로 내게 보이셨으니 주의 앞에서 나로 기쁨이 충만하게 하시리로다 하였으니"},{"n":29,"t":"형제들아 내가 조상 다윗에 대하여 담대히 말할 수 있노니 다윗이 죽어 장사되어 그 묘가 오늘까지 우리 중에 있도다"},{"n":30,"t":"그는 선지자라 하나님이 이미 맹세하사 그 자손 중에서 한 사람을 그 위에 앉게 하리라 하심을 알고"},{"n":31,"t":"미리 보는 고로 그리스도의 부활하심을 말하되 저가 음부에 버림이 되지 않고 육신이 썩음을 당하지 아니하시리라 하더니"},{"n":32,"t":"이 예수를 하나님이 살리신지라 우리가 다 이 일에 증인이로다"},{"n":33,"t":"하나님이 오른손으로 예수를 높이시매 그가 약속하신 성령을 아버지께 받아서 너희 보고 듣는 이것을 부어 주셨느니라"},{"n":34,"t":"다윗은 하늘에 올라가지 못하였으나 친히 말하여 가로되 주께서 내 주에게 말씀하시기를"},{"n":35,"t":"내가 네 원수로 네 발등상 되게 하기까지 너는 내 우편에 앉았으라 하셨도다 하였으니"},{"n":36,"t":"그런즉 이스라엘 온 집이 정녕 알찌니 너희가 십자가에 못 박은 이 예수를 하나님이 주와 그리스도가 되게 하셨느니라 하니라"}]}]},"L+M+W":{"intro":"히스기야는 온 이스라엘과 유다에 사람과 편지를 보내 예루살렘에 와서 유월절을 지키라고 했어요. 어떤 사람들은 비웃었지만 몇 사람은 겸손히 예루살렘에 올라왔어요. 성전이 다시 열린 뒤 왕과 함께한 모든 사람이 엎드려 경배했어요.","main":[{"ref":"역대하 30:1","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=2ch&chap=30&sec=1","verses":[{"n":1,"t":"히스기야가 온 이스라엘과 유다에 보내고 또 에브라임과 므낫세에 편지를 보내어 예루살렘 여호와의 전에 와서 이스라엘 하나님 여호와를 위하여 유월절을 지키라 하니라"}]},{"ref":"역대하 29:29","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=2ch&chap=29&sec=1","verses":[{"n":29,"t":"제사 드리기를 마치매 왕과 그 함께 있는 자가 다 엎드려 경배하니라"}]}],"more":[{"ref":"역대하 30:6","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=2ch&chap=30&sec=1","verses":[{"n":6,"t":"보발군들이 왕과 방백들의 편지를 받아가지고 왕의 명을 좇아 온 이스라엘과 유다에 두루 다니며 전하니 일렀으되 이스라엘 자손들아 너희는 아브라함과 이삭과 이스라엘의 하나님 여호와께로 돌아 오라 그리하면 저가 너희 남은자 곧 앗수르 왕의 손에서 벗어난 자에게로 돌아오시리라"}]},{"ref":"역대하 30:7-9","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=2ch&chap=30&sec=1","verses":[{"n":7,"t":"너희 열조와 너희 형제 같이 하지 말라 저희가 그 열조의 하나님 여호와께 범죄한고로 여호와께서 멸망에 붙이신 것을 너희가 목도하는 바니라"},{"n":8,"t":"그런즉 너희 열조 같이 목을 곧게 하지말고 여호와께 귀순하여 영원히 거룩케 하신 전에 들어가서 너희 하나님 여호와를 섬겨 그 진노가 너희에게서 떠나게 하라"},{"n":9,"t":"너희가 만일 여호와께 돌아오면 너희 형제와 너희 자녀가 사로잡은 자에게서 자비를 입어 다시 이 땅으로 돌아오리라 너희 하나님 여호와는 은혜로우시고 자비하신지라 너희가 그에게로 돌아오면 그 얼굴을 너희에게서 돌이키지 아니하시리라 하였더라"}]}]},"L+P+R":{"intro":"여호수아는 아이 성 앞에서 패한 뒤 여호와의 궤 앞에 엎드려 하나님께 말씀드렸어요. 하나님이 아이 성을 칠 방법을 일러 주시자 용사 삼만 명을 뽑아 밤에 보냈어요. 성 뒤에 복병을 두는 작전으로 아이 성을 치게 했어요.","main":[{"ref":"여호수아 7:6","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=jos&chap=7&sec=1","verses":[{"n":6,"t":"여호수아가 옷을 찢고 이스라엘 장로들과 함께 여호와의 궤 앞에서 땅에 엎드려 머리에 티끌을 무릅쓰고 저물도록 있다가"}]},{"ref":"여호수아 8:3","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=jos&chap=8&sec=1","verses":[{"n":3,"t":"이에 여호수아가 일어나서 군사와 함께 아이로 올라가려 하여 용사 삼만명을 뽑아 밤에 보내며"}]}],"more":[{"ref":"여호수아 7:7-9","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=jos&chap=7&sec=1","verses":[{"n":7,"t":"여호수아가 가로되 슬프도소이다 주 여호와여 어찌하여 이 백성을 인도하여 요단을 건너게 하시고 우리를 아모리 사람의 손에 붙여 멸망시키려 하셨나이까 우리가 요단 저편을 족하게 여겨 거하였더면 좋을뻔 하였나이다"},{"n":8,"t":"주여 이스라엘이 그 대적 앞에서 돌아섰으니 내가 무슨 말을 하오리이까"},{"n":9,"t":"가나안 사람과 이 땅 모든 거민이 이를 듣고 우리를 둘러싸고 우리 이름을 세상에서 끊으리니 주의 크신 이름을 위하여 어떻게 하시려나이까"}]},{"ref":"여호수아 8:1-2","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=jos&chap=8&sec=1","verses":[{"n":1,"t":"여호와께서 여호수아에게 이르시되 두려워 말라 놀라지 말라 군사를 다 거느리고 일어나 아이로 올라가라 보라 내가 아이 왕과 그 백성과 그 성읍과 그 땅을 다 네 손에 주었노니"},{"n":2,"t":"너는 여리고와 그 왕에게 행한것 같이 아이와 그 왕에게 행하되 오직 거기서 탈취할 물건과 가축은 스스로 취하라 너는 성 뒤에 복병할찌니라"}]},{"ref":"여호수아 8:4-8","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=jos&chap=8&sec=1","verses":[{"n":4,"t":"그들에게 명하여 가로되 너희는 성읍 뒤로 가서 성읍을 향하고 매복하되 그 성읍에 너무 멀리 하지 말고 다 스스로 예비하라"},{"n":5,"t":"나와 나를 좇는 모든 백성은 다 성읍으로 가까이 가리니 그들이 처음과 같이 우리에게로 쳐 올라 올것이라 그리할 때에 우리가 그들 앞에서 도망하면"},{"n":6,"t":"그들이 나와서 우리를 따르며 스스로 이르기를 그들이 처음과 같이 우리 앞에서 도망한다 하고 우리의 유인을 받아 그 성읍에서 멀리 떠날것이라 우리가 그 앞에서 도망하거든"},{"n":7,"t":"너희는 매복한 곳에서 일어나서 그 성읍을 점령하라 너희 하나님 여호와께서 너희 손에 붙이시리라"},{"n":8,"t":"너희가 성읍을 취하거든 그것을 불살라 여호와의 말씀대로 행하라 보라 내가 너희에게 명하였느니라 하고"}]}]},"L+P+S":{"intro":"회중에 재앙이 퍼지자 아론은 향로에 향을 담아 회중 가운데로 달려가 속죄했어요. 아론이 죽은 자와 산 자 사이에 서자 재앙이 그쳤어요. 아론과 아들들은 이스라엘 자손에게 복을 빌도록 명령받았어요.","main":[{"ref":"민수기 16:48","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=num&chap=16&sec=1","verses":[{"n":48,"t":"죽은 자와 산 자 사이에 섰을 때에 염병이 그치니라"}]},{"ref":"민수기 6:23","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=num&chap=6&sec=1","verses":[{"n":23,"t":"아론과 그 아들들에게 고하여 이르기를 너희는 이스라엘 자손을 위하여 이렇게 축복하여 이르되"}]}],"more":[{"ref":"민수기 16:46","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=num&chap=16&sec=1","verses":[{"n":46,"t":"이에 모세가 아론에게 이르되 너는 향로를 취하고 단의 불을 그것에 담고 그 위에 향을 두어가지고 급히 회중에게로 가서 그들을 위하여 속죄하라 여호와께서 진노하셨으므로 염병이 시작되었음이니라"}]},{"ref":"민수기 16:47","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=num&chap=16&sec=1","verses":[{"n":47,"t":"아론이 모세의 명을 좇아 향로를 가지고 회중에게로 달려 간즉 백성 중에 염병이 시작되었는지라 이에 백성을 위하여 속죄하고"}]},{"ref":"민수기 6:22","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=num&chap=6&sec=1","verses":[{"n":22,"t":"여호와께서 모세에게 일러 가라사대"}]},{"ref":"민수기 6:24-27","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=num&chap=6&sec=1","verses":[{"n":24,"t":"여호와는 네게 복을 주시고 너를 지키시기를 원하며"},{"n":25,"t":"여호와는 그 얼굴로 네게 비취사 은혜 베푸시기를 원하며"},{"n":26,"t":"여호와는 그 얼굴을 네게로 향하여 드사 평강 주시기를 원하노라 할찌니라 하라"},{"n":27,"t":"그들은 이같이 내 이름으로 이스라엘 자손에게 축복할찌니 내가 그들에게 복을 주리라"}]}]},"L+P+T":{"intro":"모세는 백성이 금 송아지를 만들었을 때 하나님께 엎드려 간구했어요. 장인의 말을 듣고 능력 있는 사람들을 택해 천부장, 백부장, 오십부장, 십부장으로 세웠어요. 백성에게 규례와 법도를 가르쳤다고도 말했어요.","main":[{"ref":"출애굽기 18:25","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=exo&chap=18&sec=1","verses":[{"n":25,"t":"이스라엘 무리 중에서 재덕이 겸전한 자를 빼서 그들로 백성의 두목 곧 천부장과 백부장과 오십부장과 십부장을 삼으매"}]},{"ref":"출애굽기 32:11","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=exo&chap=32&sec=1","verses":[{"n":11,"t":"모세가 그 하나님 여호와께 구하여 가로되 여호와여 어찌하여 그 큰 권능과 강한 손으로 애굽 땅에서 인도하여 내신 주의 백성에게 진노하시나이까"}]}],"more":[{"ref":"출애굽기 18:24","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=exo&chap=18&sec=1","verses":[{"n":24,"t":"이에 모세가 자기 장인의 말을 듣고 그 모든 말대로 하여"}]},{"ref":"출애굽기 18:26","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=exo&chap=18&sec=1","verses":[{"n":26,"t":"그들이 때를 따라 백성을 재판하되 어려운 일은 모세에게 베풀고 쉬운 일은 자단하더라"}]},{"ref":"출애굽기 32:12-14","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=exo&chap=32&sec=1","verses":[{"n":12,"t":"어찌하여 애굽 사람으로 이르기를 여호와가 화를 내려 그 백성을 산에서 죽이고 지면에서 진멸하려고 인도하여 내었다 하게 하려하시나이까 주의 맹렬한 노를 그치시고 뜻을 돌이키사 주의 백성에게 이 화를 내리지 마옵소서"},{"n":13,"t":"주의 종 아브라함과 이삭과 이스라엘을 기억하소서 주께서 주를 가리켜 그들에게 맹세하여 이르시기를 내가 너희 자손을 하늘의 별처럼 많게 하고 나의 허락한 이 온 땅을 너희의 자손에게 주어 영영한 기업이 되게 하리라 하셨나이다"},{"n":14,"t":"여호와께서 뜻을 돌이키사 말씀하신 화를 그 백성에게 내리지 아니하시니라"}]},{"ref":"신명기 4:1","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=deu&chap=4&sec=1","verses":[{"n":1,"t":"이스라엘아 이제 내가 너희에게 가르치는 규례와 법도를 듣고 준행하라 그리하면 너희가 살 것이요 너희의 열조의 하나님 여호와께서 너희에게 주시는 땅에 들어가서 그것을 얻게 되리라"}]},{"ref":"신명기 4:5","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=deu&chap=4&sec=1","verses":[{"n":5,"t":"내가 나의 하나님 여호와의 명하신대로 규례와 법도를 너희에게 가르쳤나니 이는 너희로 들어가서 기업으로 얻을 땅에서 그대로 행하게 하려 함인즉"}]}]},"L+P+W":{"intro":"아사는 이방 제단과 우상을 없애고 유다 사람들에게 여호와를 찾으라고 명했어요. 큰 군대가 쳐들어왔을 때에는 여호와께 부르짖었어요. 여호와의 제단을 중수하고 백성을 모아 제사를 드렸어요.","main":[{"ref":"역대하 14:11","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=2ch&chap=14&sec=1","verses":[{"n":11,"t":"그 하나님 여호와께 부르짖어 가로되 여호와여 강한 자와 약한 자 사이에는 주 밖에 도와줄 이가 없사오니 우리 하나님 여호와여 우리를 도우소서 우리가 주를 의지하오며 주의 이름을 의탁하옵고 이 많은 무리를 치러 왔나이다 여호와여 주는 우리 하나님이시오니 원컨대 사람으로 주를 이기지 못하게 하옵소서 하였더니"}]},{"ref":"역대하 15:8","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=2ch&chap=15&sec=1","verses":[{"n":8,"t":"아사가 이 말 곧 선지자 오뎃의 예언을 듣고 마음을 강하게 하여 가증한 물건을 유다와 베냐민 온 땅에서 제하고 또 에브라임 산지에서 빼앗은 성읍들에서 제하고 또 여호와의 낭실 앞 여호와의 단을 중수하고"}]}],"more":[{"ref":"역대하 14:2","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=2ch&chap=14&sec=1","verses":[{"n":2,"t":"아사가 그 하나님 여호와 보시기에 선과 정의를 행하여"}]},{"ref":"역대하 14:3-5","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=2ch&chap=14&sec=1","verses":[{"n":3,"t":"이방 제단과 산당을 없이하고 주상을 훼파하며 아세라 상을 찍고"},{"n":4,"t":"유다 사람을 명하여 그 열조의 하나님 여호와를 구하게 하며 그 율법과 명령을 행하게 하고"},{"n":5,"t":"또 유다 모든 성읍에서 산당과 태양상을 없이하매 나라가 그 앞에서 평안함을 얻으니라"}]},{"ref":"역대하 15:9-15","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=2ch&chap=15&sec=1","verses":[{"n":9,"t":"또 유다와 베냐민의 무리를 모으고 에브라임과 므낫세와 시므온 가운데서 나와서 저희 중에 우거하는 자를 모았으니 이는 이스라엘 사람들이 아사의 하나님 여호와께서 그와 함께하심을 보고 아사에게로 돌아오는 자가 많았음이더라"},{"n":10,"t":"아사왕 십 오년 삼월에 저희가 예루살렘에 모이고"},{"n":11,"t":"그 날에 노략하여 온 물건 중에서 소 칠백과 양 칠천으로 여호와께 제사를 드리고"},{"n":12,"t":"또 마음을 다하고 성품을 다하여 열조의 하나님 여호와를 찾기로 언약하고"},{"n":13,"t":"무릇 이스라엘 하나님 여호와를 찾지 아니하는 자는 대소 남녀를 무론하고 죽이는 것이 마땅하다 하고"},{"n":14,"t":"무리가 큰 소리로 부르며 피리와 나팔을 불어 여호와께 맹세하매"},{"n":15,"t":"온 유다가 이 맹세를 기뻐한지라 무리가 마음을 다하여 맹세하고 뜻을 다하여 여호와를 찾았으므로 여호와께서도 저희의 만난바가 되시고 그 사방에 평안을 주셨더라"}]}]},"L+R+S":{"intro":"나발의 아내 아비가일은 다윗이 자기 집을 해하려 하자 급히 떡과 양을 준비해 나귀에 싣고 길을 나섰어요. 다윗 앞에 엎드려 그가 직접 피를 흘리지 않도록 간곡히 말했어요. 다윗은 그의 지혜를 칭찬하고 청을 허락했어요.","main":[{"ref":"사무엘상 25:18","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=1sa&chap=25&sec=1","verses":[{"n":18,"t":"아비가일이 급히 떡 이백덩이와 포도주 두 가죽부대와 잡아 준비한 양 다섯과 볶은 곡식 다섯 세아와 건포도 백송이와 무화과뭉치 이백을 취하여 나귀들에게 싣고"}]},{"ref":"사무엘상 25:32","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=1sa&chap=25&sec=1","verses":[{"n":32,"t":"다윗이 아비가일에게 이르되 오늘날 너를 보내어 나를 영접케 하신 이스라엘의 하나님 여호와를 찬송할찌로다"}]}],"more":[{"ref":"사무엘상 25:19","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=1sa&chap=25&sec=1","verses":[{"n":19,"t":"소년들에게 이르되 내 앞서 가라 나는 너희 뒤에 가리라 하고 그 남편 나발에게는 고하지 아니하니라"}]},{"ref":"사무엘상 25:23-31","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=1sa&chap=25&sec=1","verses":[{"n":23,"t":"아비가일이 다윗을 보고 급히 나귀에서 내려 다윗의 앞에 엎드려 그 얼굴을 땅에 대니라"},{"n":24,"t":"그가 다윗의 발에 엎드려 가로되 내 주여 청컨대 이 죄악을 나 곧 내게로 돌리시고 여종으로 주의 귀에 말하게 하시고 이 여종의 말을 들으소서"},{"n":25,"t":"원하옵나니 내 주는 이 불량한 사람 나발을 개의치 마옵소서 그 이름이 그에게 적당하니 그 이름이 나발이라 그는 미련한 자니이다 여종은 내 주의 보내신 소년들을 보지 못하였나이다"},{"n":26,"t":"내 주여 여호와께서 사시고 내 주도 살아계시거니와 내 주의 손으로 피를 흘려 친히 보수하시는 일을 여호와께서 막으셨으니 내 주의 원수들과 내 주를 해하려 하는 자들은 나발과 같이 되기를 원하나이다"},{"n":27,"t":"여종이 내 주에게 가져온 이 예물로 내 주를 좇는 이 소년들에게 주게 하시고"},{"n":28,"t":"주의 여종의 허물을 사하여 주옵소서 여호와께서 반드시 내 주를 위하여 든든한 집을 세우시리니 이는 내 주께서 여호와의 싸움을 싸우심이요 내 주의 일생에 내 주에게서 악한 일을 찾을 수 없음이니이다"},{"n":29,"t":"사람이 일어나서 내 주를 쫓아 내 주의 생명을 찾을찌라도 내 주의 생명은 내 주의 하나님 여호와와 함께 생명싸개 속에 싸였을 것이요 내 주의 원수들의 생명은 물매로 던지듯 여호와께서 그것을 던지시리이다"},{"n":30,"t":"여호와께서 내 주에 대하여 하신 말씀대로 모든 선을 내 주에게 행하사 내 주를 이스라엘의 지도자로 세우신 때에"},{"n":31,"t":"내 주께서 무죄한 피를 흘리셨다든지 내 주께서 친히 보수하셨다든지 함을 인하여 슬퍼하실 것도 없고 내 주의 마음에 걸리는 것도 없으시리니 다만 여호와께서 내 주를 후대하신 때에 원컨대 내 주의 여종을 생각하소서"}]},{"ref":"사무엘상 25:33-35","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=1sa&chap=25&sec=1","verses":[{"n":33,"t":"또 네 지혜를 칭찬할찌며 또 네게 복이 있을찌로다 오늘날 내가 피를 흘릴 것과 친히 보수하는 것을 네가 막았느니라"},{"n":34,"t":"나를 막아 너를 해하지 않게 하신 이스라엘의 하나님 여호와의 사심으로 맹세하노니 네가 급히 와서 나를 영접지 아니하였더면 밝는 아침에는 과연 나발에게 한 남자도 남겨두지 아니하였으리라"},{"n":35,"t":"다윗이 그가 가져온 것을 그의 손에서 받고 그에게 이르되 네 집으로 평안히 올라가라 내가 네 말을 듣고 네 청을 허락하노라"}]}]},"L+R+T":{"intro":"솔로몬은 두 여인이 한 아이를 두고 다투자 칼을 가져오게 하고 아이를 나누라고 말해 진짜 어머니를 가려냈어요. 온 이스라엘이 그 판결을 듣고 그의 지혜를 두려워했어요. 그는 잠언 삼천 가지를 말했고 사람들은 그의 지혜를 들으러 왔어요.","main":[{"ref":"열왕기상 3:28","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=1ki&chap=3&sec=1","verses":[{"n":28,"t":"온 이스라엘이 왕의 심리하여 판결함을 듣고 왕을 두려워하였으니 이는 하나님의 지혜가 저의 속에 있어 판결함을 봄이더라"}]},{"ref":"열왕기상 4:32","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=1ki&chap=4&sec=1","verses":[{"n":32,"t":"저가 잠언 삼천을 말하였고 그 노래는 일천 다섯이며"}]}],"more":[{"ref":"열왕기상 3:24","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=1ki&chap=3&sec=1","verses":[{"n":24,"t":"또 가로되 칼을 내게로 가져오라 하니 칼을 왕의 앞으로 가져온지라"}]},{"ref":"열왕기상 3:25-27","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=1ki&chap=3&sec=1","verses":[{"n":25,"t":"왕이 이르되 산 아들을 둘에 나눠 반은 이에게 주고 반은 저에게 주라"},{"n":26,"t":"그 산 아들의 어미되는 계집이 그 아들을 위하여 마음이 불붙는것 같아서 왕께 아뢰어 가로되 청컨대 내 주여 산 아들을 저에게 주시고 아무쪼록 죽이지 마옵소서 하되 한 계집은 말하기를 내 것도 되게 말고 네 것도 되게 말고 나누게 하라 하는지라"},{"n":27,"t":"왕이 대답하여 가로되 산 아들을 저 계집에게 주고 결코 죽이지 말라 저가 그 어미니라 하매"}]},{"ref":"열왕기상 4:33-34","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=1ki&chap=4&sec=1","verses":[{"n":33,"t":"저가 또 초목을 논하되 레바논 백향목으로부터 담에 나는 우슬초까지 하고 저가 또 짐승과 새와 기어 다니는 것과 물고기를 논한지라"},{"n":34,"t":"모든 민족 중에서 솔로몬의 지혜의 소문을 들은 천하 모든 왕 중에서 그 지혜를 들으러 왔더라"}]}]},"L+R+W":{"intro":"다윗은 레위 사람의 어른들에게 노래하는 사람들을 세워 비파와 수금과 제금으로 즐거운 소리를 내게 하라고 명령했어요. 여호와께 찬송하려고 만든 악기로 찬송하는 사람들이 있었어요. 성전 준비를 마친 뒤에는 온 회중 앞에서 여호와를 송축했어요.","main":[{"ref":"역대상 15:16","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=1ch&chap=15&sec=1","verses":[{"n":16,"t":"다윗이 레위 사람의 어른들에게 명하여 그 형제 노래하는 자를 세우고 비파와 수금과 제금 등의 악기를 울려서 즐거운 소리를 크게 내라 하매"}]},{"ref":"역대상 29:10","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=1ch&chap=29&sec=1","verses":[{"n":10,"t":"다윗이 온 회중 앞에서 여호와를 송축하여 가로되 우리 조상 이스라엘의 하나님 여호와여 주는 영원히 송축을 받으시옵소서"}]}],"more":[{"ref":"역대상 23:5","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=1ch&chap=23&sec=1","verses":[{"n":5,"t":"사천은 문지기요 사천은 다윗의 찬송하기 위하여 지은 악기로 여호와를 찬송하는 자라"}]},{"ref":"역대상 29:11-13","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=1ch&chap=29&sec=1","verses":[{"n":11,"t":"여호와여 광대하심과 권능과 영광과 이김과 위엄이 다 주께 속하였사오니 천지에 있는 것이 다 주의 것이로소이다 여호와여 주권도 주께 속하였사오니 주는 높으사 만유의 머리심이니이다"},{"n":12,"t":"부와 귀가 주께로 말미암고 또 주는 만유의 주재가 되사 손에 권세와 능력이 있사오니 모든 자를 크게 하심과 강하게 하심이 주의 손에 있나이다"},{"n":13,"t":"우리 하나님이여 이제 우리가 주께 감사하오며 주의 영화로운 이름을 찬양하나이다"}]}]},"L+S+T":{"intro":"요셉은 주인 보디발의 집에서 가정 총무가 되어 모든 소유를 맡았어요. 애굽의 총리가 된 뒤에는 온 땅을 돌아다니며 일곱 해 풍년의 곡식을 거두어 각 성에 쌓았어요. 시편은 그가 지혜로 장로들을 가르치게 되었다고 노래해요.","main":[{"ref":"창세기 41:40","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=gen&chap=41&sec=1","verses":[{"n":40,"t":"너는 내 집을 치리하라 내 백성이 다 네 명을 복종하리니 나는 너보다 높음이 보좌 뿐이니라"}]},{"ref":"창세기 41:48","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=gen&chap=41&sec=1","verses":[{"n":48,"t":"요셉이 애굽 땅에 있는 그 칠년 곡물을 거두어 각성에 저축하되 각성 주위의 밭의 곡물을 그 성중에 저장하매"}]}],"more":[{"ref":"창세기 41:41","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=gen&chap=41&sec=1","verses":[{"n":41,"t":"바로가 또 요셉에게 이르되 내가 너로 애굽 온 땅을 총리하게 하노라 하고"}]},{"ref":"창세기 41:46","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=gen&chap=41&sec=1","verses":[{"n":46,"t":"요셉이 애굽왕 바로 앞에 설 때에 삼십세라 그가 바로 앞을 떠나 애굽 온 땅을 순찰하니"}]},{"ref":"창세기 41:47","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=gen&chap=41&sec=1","verses":[{"n":47,"t":"일곱해 풍년에 토지 소출이 심히 많은지라"}]},{"ref":"창세기 41:49","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=gen&chap=41&sec=1","verses":[{"n":49,"t":"저장한 곡식이 바다 모래 같이 심히 많아 세기를 그쳤으니 그 수가 한이 없음이었더라"}]},{"ref":"창세기 39:4-6","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=gen&chap=39&sec=1","verses":[{"n":4,"t":"요셉이 그 주인에게 은혜를 입어 섬기매 그가 요셉으로 가정 총무를 삼고 자기 소유를 다 그 손에 위임하니"},{"n":5,"t":"그가 요셉에게 자기 집과 그 모든 소유물을 주관하게 한 때부터 여호와께서 요셉을 위하여 그 애굽 사람의 집에 복을 내리시므로 여호와의 복이 그의 집과 밭에 있는 모든 소유에 미친지라"},{"n":6,"t":"주인이 그 소유를 다 요셉의 손에 위임하고 자기 식료 외에는 간섭하지 아니하였더라 요셉은 용모가 준수하고 아담하였더라"}]},{"ref":"시편 105:21-22","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=psa&chap=105&sec=1","verses":[{"n":21,"t":"저로 그 집의 주관자를 삼아 그 모든 소유를 관리케 하고"},{"n":22,"t":"임의로 백관을 제어하며 지혜로 장로들을 교훈하게 하였도다"}]}]},"L+S+W":{"intro":"제사장 여호야다는 용기를 내어 백부장들과 언약을 세웠어요. 성전 직원을 세워 번제와 노래의 규례를 다시 지키게 했어요. 한 궤의 뚜껑에 구멍을 뚫어 헌금을 모으게 하고 그 은으로 성전을 수리하게 했어요.","main":[{"ref":"역대하 23:18","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=2ch&chap=23&sec=1","verses":[{"n":18,"t":"여호야다가 여호와의 전의 직원을 세워 제사장 레위 사람의 수하에 맡기니 이들은 다윗이 전에 그 반차를 나누어서 여호와의 전에서 모세의 율법에 기록한대로 여호와께 번제를 드리며 자기의 정한 규례대로 즐거이 부르고 노래하게 하였던 자더라"}]},{"ref":"열왕기하 12:9","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=2ki&chap=12&sec=1","verses":[{"n":9,"t":"제사장 여호야다가 한 궤를 취하여 그 뚜껑에 구멍을 뚫어 여호와의 전문 어귀 우편 곧 단 옆에 두매 무릇 여호와의 전에 가져 오는 은을 다 문을 지키는 제사장들이 그 궤에 넣더라"}]}],"more":[{"ref":"역대하 23:1","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=2ch&chap=23&sec=1","verses":[{"n":1,"t":"제 칠년에 여호야다가 세력을 내어 백부장 곧 여로함의 아들 아사랴와 여호하난의 아들 이스마엘과 오벳의 아들 아사랴와 아다야의 아들 마아세야와 시그리의 아들 엘리사밧 등으로 더불어 언약을 세우매"}]},{"ref":"역대하 23:8","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=2ch&chap=23&sec=1","verses":[{"n":8,"t":"레위 사람과 유다 무리가 제사장 여호야다의 모든 명한 바를 준행하여 각기 수하의 안식일에 입번할 자와 안식일에 출번할 자를 거느리고 있으니 이는 제사장 여호야다가 출번하는 자를 보내지 아니함이더라"}]},{"ref":"열왕기하 12:10-11","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=2ki&chap=12&sec=1","verses":[{"n":10,"t":"이에 그 궤 가운데 은이 많은 것을 보면 왕의 서기와 대제사장이 올라와서 여호와의 전에 있는대로 그 은을 계수하여 봉하고"},{"n":11,"t":"그 달아본 은을 일하는 자 곧 여호와의 전을 맡은 자의 손에 붙이면 저희는 또 여호와의 전을 수리하는 목수와 건축하는 자들에게 주고"}]},{"ref":"역대하 24:14","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=2ch&chap=24&sec=1","verses":[{"n":14,"t":"필역한 후에 그 남은 돈을 왕과 여호야다의 앞으로 가져온고로 그것으로 여호와의 전에 쓸 그릇을 만들었으니 곧 섬겨 제사 드리는 그릇이며 또 숟가락과 금, 은그릇들이라 여호야다가 세상에 사는 모든 날에 여호와의 전에 항상 번제를 드렸더라"}]}]},"L+T+W":{"intro":"요시야 왕은 유다와 예루살렘의 모든 장로를 불러 모았어요. 성전에서 발견한 언약책의 말씀을 모든 백성에게 읽어 들려주었어요. 그리고 유월절을 지켰는데, 사무엘 이후 그렇게 지킨 적이 없었어요.","main":[{"ref":"역대하 34:30","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=2ch&chap=34&sec=1","verses":[{"n":30,"t":"이에 여호와의 전에 올라가매 유다 모든 사람과 예루살렘 거민과 제사장들과 레위 사람들과 모든 백성이 무론노소하고 다 함께 한지라 왕이 여호와의 전 안에서 발견한 언약책의 모든 말씀을 읽어 무리의 귀에 들리고"}]},{"ref":"역대하 35:1","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=2ch&chap=35&sec=1","verses":[{"n":1,"t":"요시야가 예루살렘 여호와 앞에서 유월절을 지켜 정월 십 사일에 유월절 어린 양을 잡으니라"}]}],"more":[{"ref":"역대하 34:29","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=2ch&chap=34&sec=1","verses":[{"n":29,"t":"왕이 보내어 유다와 예루살렘의 모든 장로를 불러 모으고"}]},{"ref":"역대하 35:16-18","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=2ch&chap=35&sec=1","verses":[{"n":16,"t":"이와 같이 당일에 여호와를 섬길 일이 다 준비되매 요시야왕의 명대로 유월절을 지키며 번제를 여호와의 단에 드렸으며"},{"n":17,"t":"그 때에 모인 이스라엘 자손이 유월절을 지키고 연하여 무교절을 칠일 동안 지켰으니"},{"n":18,"t":"선지자 사무엘 이후로 이스라엘 가운데서 유월절을 이같이 지키지 못하였고 이스라엘 열왕도 요시야가 제사장들과 레위 사람들과 모인 온 유다와 이스라엘 무리와 예루살렘 거민과 함께 지킨 것처럼은 유월절을 지키지 못하였더라"}]}]},"M+P+R":{"intro":"엘리야는 갈멜 산에 모인 백성에게 어느 때까지 둘 사이에서 머뭇거리겠느냐고 물었어요. 제물과 나무 위에 물을 세 번 붓게 한 뒤 하나님께 기도했어요. 이 백성이 여호와가 하나님이심을 알게 해 달라고 구했어요.","main":[{"ref":"열왕기상 18:21","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=1ki&chap=18&sec=1","verses":[{"n":21,"t":"엘리야가 모든 백성에게 가까이 나아가 이르되 너희가 어느때까지 두 사이에서 머뭇머뭇 하려느냐 여호와가 만일 하나님이면 그를 좇고 바알이 만일 하나님이면 그를 좇을찌니라 하니 백성이 한 말도 대답지 아니하는지라"}]},{"ref":"열왕기상 18:37","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=1ki&chap=18&sec=1","verses":[{"n":37,"t":"여호와여 내게 응답하옵소서 내게 응답하옵소서 이 백성으로 주 여호와는 하나님이신 것과 주는 저희의 마음으로 돌이키게 하시는 것을 알게 하옵소서 하매"}]}],"more":[{"ref":"열왕기상 18:36","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=1ki&chap=18&sec=1","verses":[{"n":36,"t":"저녁 소제 드릴 때에 이르러 선지자 엘리야가 나아가서 말하되 아브라함과 이삭과 이스라엘의 하나님 여호와여 주께서 이스라엘 중에서 하나님이 되심과 내가 주의 종이 됨과 내가 주의 말씀대로 이 모든 일을 행하는 것을 오늘날 알게 하옵소서"}]},{"ref":"열왕기상 18:33-35","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=1ki&chap=18&sec=1","verses":[{"n":33,"t":"또 나무를 벌이고 송아지의 각을 떠서 나무 위에 놓고 이르되 통 넷에 물을 채워다가 번제물과 나무 위에 부으라 하고"},{"n":34,"t":"또 이르되 다시 그리하라 하여 다시 그리하니 또 이르되 세번 그리하라 하여 세번 그리하니"},{"n":35,"t":"물이 단으로 두루 흐르고 도랑에도 물이 가득하게 되었더라"}]}]},"M+P+S":{"intro":"루디아가 바울의 말을 들을 때 주께서 그의 마음을 열어 주셨어요. 그와 집안이 세례를 받은 뒤 루디아는 바울 일행에게 자기 집에 와서 머물라고 간청했어요. 바울 일행은 감옥에서 나온 뒤에도 그의 집에 들렀어요.","main":[{"ref":"사도행전 16:14","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=act&chap=16&sec=1","verses":[{"n":14,"t":"두아디라성의 자주 장사로서 하나님을 공경하는 루디아라 하는 한 여자가 들었는데 주께서 그 마음을 열어 바울의 말을 청종하게 하신지라"}]},{"ref":"사도행전 16:15","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=act&chap=16&sec=1","verses":[{"n":15,"t":"저와 그 집이 다 세례를 받고 우리에게 청하여 가로되 만일 나를 주 믿는 자로 알거든 내 집에 들어와 유하라 하고 강권하여 있게 하니라"}]}],"more":[{"ref":"사도행전 16:13","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=act&chap=16&sec=1","verses":[{"n":13,"t":"안식일에 우리가 기도처가 있는가 하여 문밖 강 가에 나가 거기 앉아서 모인 여자들에게 말하더니"}]},{"ref":"사도행전 16:40","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=act&chap=16&sec=1","verses":[{"n":40,"t":"두 사람이 옥에서 나가 루디아의 집에 들어가서 형제들을 만나보고 위로하고 가니라"}]}]},"M+P+T":{"intro":"골로새 교회 사람들은 에바브라에게 복음을 배웠어요. 바울은 에바브라를 그리스도의 신실한 일꾼이라 부르며 그가 늘 이 교회를 위해 기도하며 애쓴다고 썼어요.","main":[{"ref":"골로새서 4:12","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=col&chap=4&sec=1","verses":[{"n":12,"t":"그리스도 예수의 종인 너희에게서 온 에바브라가 너희에게 문안하니 저가 항상 너희를 위하여 애써 기도하여 너희로 하나님의 모든 뜻 가운데서 완전하고 확신있게 서기를 구하나니"}]},{"ref":"골로새서 1:7","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=col&chap=1&sec=1","verses":[{"n":7,"t":"이와 같이 우리와 함께 종된 사랑하는 에바브라에게 너희가 배웠나니 그는 너희를 위하여 그리스도의 신실한 일군이요"}]}],"more":[{"ref":"골로새서 1:6","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=col&chap=1&sec=1","verses":[{"n":6,"t":"이 복음이 이미 너희에게 이르매 너희가 듣고 참으로 하나님의 은혜를 깨달은 날부터 너희 중에서와 같이 또한 온 천하에서도 열매를 맺어 자라는도다"}]}]},"M+P+W":{"intro":"선지자 안나는 오랫동안 과부로 지내며 성전을 떠나지 않고 밤낮 금식과 기도로 섬겼어요. 아기 예수를 만난 때에는 하나님께 감사했어요. 예루살렘의 구원을 기다리는 모든 사람에게 아기에 대해 말했어요.","main":[{"ref":"누가복음 2:37","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=luk&chap=2&sec=1","verses":[{"n":37,"t":"과부 된지 팔십 사년이라 이 사람이 성전을 떠나지 아니하고 주야에 금식하며 기도함으로 섬기더니"}]},{"ref":"누가복음 2:38","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=luk&chap=2&sec=1","verses":[{"n":38,"t":"마침 이 때에 나아와서 하나님께 감사하고 예루살렘의 구속됨을 바라는 모든 사람에게 이 아기에 대하여 말하니라"}]}],"more":[]},"M+R+S":{"intro":"안드레는 시몬에게 메시아를 만났다고 알리고 예수께 데려갔어요. 큰 무리가 먹을 것이 없을 때에는 한 아이가 가진 보리떡 다섯 개와 물고기 두 마리를 예수께 알렸어요. 헬라 사람들이 예수를 만나고 싶어 하자 그 부탁을 예수께 전했어요.","main":[{"ref":"요한복음 1:42","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=jhn&chap=1&sec=1","verses":[{"n":42,"t":"데리고 예수께로 오니 예수께서 보시고 가라사대 네가 요한의 아들 시몬이니 장차 게바라 하리라 하시니라 (게바는 번역하면 베드로라)"}]},{"ref":"요한복음 6:9","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=jhn&chap=6&sec=1","verses":[{"n":9,"t":"여기 한 아이가 있어 보리떡 다섯 개와 물고기 두 마리를 가졌나이다 그러나 그것이 이 많은 사람에게 얼마나 되겠삽나이까"}]}],"more":[{"ref":"요한복음 1:40","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=jhn&chap=1&sec=1","verses":[{"n":40,"t":"요한의 말을 듣고 예수를 좇는 두 사람 중에 하나는 시몬 베드로의 형제 안드레라"}]},{"ref":"요한복음 1:41","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=jhn&chap=1&sec=1","verses":[{"n":41,"t":"그가 먼저 자기의 형제 시몬을 찾아 말하되 우리가 메시야를 만났다 하고 (메시야는 번역하면 그리스도라)"}]},{"ref":"요한복음 6:8","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=jhn&chap=6&sec=1","verses":[{"n":8,"t":"제자 중 하나 곧 시몬 베드로의 형제 안드레가 예수께 여짜오되"}]},{"ref":"요한복음 12:20-22","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=jhn&chap=12&sec=1","verses":[{"n":20,"t":"명절에 예배하러 올라온 사람 중에 헬라인 몇이 있는데"},{"n":21,"t":"저희가 갈릴리 벳새다 사람 빌립에게 가서 청하여 가로되 선생이여 우리가 예수를 뵈옵고자 하나이다 하니"},{"n":22,"t":"빌립이 안드레에게 가서 말하고 안드레와 빌립이 예수께 가서 여짜온대"}]}]},"M+R+T":{"intro":"아볼로는 성경에 능통하고 예수에 대하여 열심히 말하고 가르쳤어요. 브리스길라와 아굴라에게 하나님의 도를 더 정확히 배웠어요. 그 뒤에는 성경으로 예수가 그리스도이심을 공중 앞에서 힘 있게 밝혔어요.","main":[{"ref":"사도행전 18:24","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=act&chap=18&sec=1","verses":[{"n":24,"t":"알렉산드리아에서 난 아볼로라 하는 유대인이 에베소에 이르니 이 사람은 학문이 많고 성경에 능한 자라"}]},{"ref":"사도행전 18:28","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=act&chap=18&sec=1","verses":[{"n":28,"t":"이는 성경으로써 예수는 그리스도라고 증거하여 공중 앞에서 유력하게 유대인의 말을 이김일러라"}]}],"more":[{"ref":"사도행전 18:25-27","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=act&chap=18&sec=1","verses":[{"n":25,"t":"그가 일찍 주의 도를 배워 열심으로 예수에 관한 것을 자세히 말하며 가르치나 요한의 세례만 알 따름이라"},{"n":26,"t":"그가 회당에서 담대히 말하기를 시작하거늘 브리스길라와 아굴라가 듣고 데려다가 하나님의 도를 더 자세히 풀어 이르더라"},{"n":27,"t":"아볼로가 아가야로 건너가고자 하니 형제들이 저를 장려하며 제자들에게 편지하여 영접하라 하였더니 저가 가매 은혜로 말미암아 믿은 자들에게 많은 유익을 주니"}]}]},"M+R+W":{"intro":"요나는 니느웨로 가서 하나님의 말씀을 외쳤어요. 물고기 뱃속에서는 하나님께 기도하며 감사하는 소리로 제사를 드리겠다고 했어요. 그 뒤 니느웨 일로 화가 났을 때에도 하나님은 요나에게 말씀하셨어요.","main":[{"ref":"요나 2:9","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=jnh&chap=2&sec=1","verses":[{"n":9,"t":"나는 감사하는 목소리로 주께 제사를 드리며 나의 서원을 주께 갚겠나이다 구원은 여호와께로서 말미암나이다 하니라"}]},{"ref":"요나 3:4","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=jnh&chap=3&sec=1","verses":[{"n":4,"t":"요나가 그 성에 들어가며 곧 하룻길을 행하며 외쳐 가로되 사십일이 지나면 니느웨가 무너지리라 하였더니"}]}],"more":[{"ref":"요나 3:3","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=jnh&chap=3&sec=1","verses":[{"n":3,"t":"요나가 여호와의 말씀대로 일어나서 니느웨로 가니라 니느웨는 극히 큰 성읍이므로 삼일길이라"}]},{"ref":"요나 2:1-8","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=jnh&chap=2&sec=1","verses":[{"n":1,"t":"요나가 물고기 뱃속에서 그 하나님 여호와께 기도하여"},{"n":2,"t":"가로되 내가 받는 고난을 인하여 여호와께 불러 아뢰었삽더니 주께서 내게 대답하셨고 내가 스올의 뱃속에서 부르짖었삽더니 주께서 나의 음성을 들으셨나이다"},{"n":3,"t":"주께서 나를 깊음속 바다 가운데 던지셨으므로 큰 물이 나를 둘렀고 주의 파도와 큰 물결이 다 내 위에 넘쳤나이다"},{"n":4,"t":"내가 말하기를 내가 주의 목전에서 쫓겨났을찌라도 다시 주의 성전을 바라보겠다 하였나이다"},{"n":5,"t":"물이 나를 둘렀으되 영혼까지 하였사오며 깊음이 나를 에웠고 바다 풀이 내 머리를 쌌나이다"},{"n":6,"t":"내가 산의 뿌리까지 내려갔사오며 땅이 그 빗장으로 나를 오래도록 막았사오나 나의 하나님 여호와여 주께서 내 생명을 구덩이에서 건지셨나이다"},{"n":7,"t":"내 영혼이 내 속에서 피곤할 때에 내가 여호와를 생각하였삽더니 내 기도가 주께 이르렀사오며 주의 성전에 미쳤나이다"},{"n":8,"t":"무릇 거짓되고 헛된 것을 숭상하는 자는 자기에게 베푸신 은혜를 버렸사오나"}]},{"ref":"요나 4:1-11","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=jnh&chap=4&sec=1","verses":[{"n":1,"t":"요나가 심히 싫어하고 노하여"},{"n":2,"t":"여호와께 기도하여 가로되 여호와여 내가 고국에 있을 때에 이러하겠다고 말씀하지 아니하였나이까 그러므로 내가 빨리 다시스로 도망하였사오니 주께서는 은혜로우시며 자비로우시며 노하기를 더디하시며 인애가 크시사 뜻을 돌이켜 재앙을 내리지 아니하시는 하나님이신 줄을 내가 알았음이니이다"},{"n":3,"t":"여호와여 원컨대 이제 내 생명을 취하소서 사는 것보다 죽는 것이 내게 나음이니이다"},{"n":4,"t":"여호와께서 이르시되 너의 성냄이 어찌 합당하냐 하시니라"},{"n":5,"t":"요나가 성에서 나가서 그 성 동편에 앉되 거기서 자기를 위하여 초막을 짓고 그 그늘 아래 앉아서 성읍이 어떻게 되는 것을 보려 하니라"},{"n":6,"t":"하나님 여호와께서 박 넝쿨을 준비하사 요나 위에 가리우게 하셨으니 이는 그 머리를 위하여 그늘이 지게 하며 그 괴로움을 면케하려 하심이었더라 요나가 박 넝쿨을 인하여 심히 기뻐하였더니"},{"n":7,"t":"하나님이 벌레를 준비하사 이튿날 새벽에 그 박 넝쿨을 씹게 하시매 곧 시드니라"},{"n":8,"t":"해가 뜰 때에 하나님이 뜨거운 동풍을 준비하셨고 해는 요나의 머리에 쬐매 요나가 혼곤하여 스스로 죽기를 구하여 가로되 사는 것보다 죽는 것이 내게 나으니이다"},{"n":9,"t":"하나님이 요나에게 이르시되 네가 이 박 넝쿨로 인하여 성냄이 어찌 합당하냐 그가 대답하되 내가 성내어 죽기까지 할찌라도 합당하니이다"},{"n":10,"t":"여호와께서 가라사대 네가 수고도 아니하였고 배양도 아니하였고 하룻밤에 났다가 하룻밤에 망한 이 박 넝쿨을 네가 아꼈거든"},{"n":11,"t":"하물며 이 큰 성읍, 니느웨에는 좌우를 분변치 못하는 자가 십 이만 여명이요 육축도 많이 있나니 내가 아끼는 것이 어찌 합당치 아니하냐"}]}]},"M+S+T":{"intro":"빌립은 구제를 맡을 일곱 사람 가운데 한 사람으로 뽑혔어요. 사마리아 성에서 그리스도를 전했고, 길에서 이사야서를 읽던 에디오피아 내시에게 예수를 가르쳐 복음을 전했어요. 그는 전도자 빌립이라고 불렸어요.","main":[{"ref":"사도행전 8:5","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=act&chap=8&sec=1","verses":[{"n":5,"t":"빌립이 사마리아 성에 내려가 그리스도를 백성에게 전파하니"}]},{"ref":"사도행전 8:35","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=act&chap=8&sec=1","verses":[{"n":35,"t":"빌립이 입을 열어 이 글에서 시작하여 예수를 가르쳐 복음을 전하니"}]}],"more":[{"ref":"사도행전 8:6-8","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=act&chap=8&sec=1","verses":[{"n":6,"t":"무리가 빌립의 말도 듣고 행하는 표적도 보고 일심으로 그의 말하는 것을 좇더라"},{"n":7,"t":"많은 사람에게 붙었던 더러운 귀신들이 크게 소리를 지르며 나가고 또 많은 중풍병자와 앉은뱅이가 나으니"},{"n":8,"t":"그 성에 큰 기쁨이 있더라"}]},{"ref":"사도행전 21:8","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=act&chap=21&sec=1","verses":[{"n":8,"t":"이튿날 떠나 가이사랴에 이르러 일곱 집사 중 하나인 전도자 빌립의 집에 들어가서 유하니라"}]},{"ref":"사도행전 6:2-5","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=act&chap=6&sec=1","verses":[{"n":2,"t":"열 두 사도가 모든 제자를 불러 이르되 우리가 하나님의 말씀을 제쳐 놓고 공궤를 일삼는 것이 마땅치 아니하니"},{"n":3,"t":"형제들아 너희 가운데서 성령과 지혜가 충만하여 칭찬 듣는 사람 일곱을 택하라 우리가 이 일을 저희에게 맡기고"},{"n":4,"t":"우리는 기도하는 것과 말씀 전하는 것을 전무하리라 하니"},{"n":5,"t":"온 무리가 이 말을 기뻐하여 믿음과 성령이 충만한 사람 스데반과 또 빌립과 브로고로와 니가노르와 디몬과 바메나와 유대교에 입교한 안디옥 사람 니골라를 택하여"}]}]},"M+S+W":{"intro":"막달라 마리아는 다른 여자들과 함께 자기 소유로 예수와 제자들을 섬겼어요. 부활하신 예수를 만난 여자들은 그 발을 붙잡고 경배했어요. 마리아는 제자들에게 가서 주를 보았다고 전했어요.","main":[{"ref":"요한복음 20:18","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=jhn&chap=20&sec=1","verses":[{"n":18,"t":"막달라 마리아가 가서 제자들에게 내가 주를 보았다 하고 또 주께서 자기에게 이렇게 말씀하셨다 이르니라"}]},{"ref":"누가복음 8:3","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=luk&chap=8&sec=1","verses":[{"n":3,"t":"또 헤롯의 청지기 구사의 아내 요안나와 또 수산나와 다른 여러 여자가 함께 하여 자기들의 소유로 저희를 섬기더라"}]}],"more":[{"ref":"누가복음 8:2","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=luk&chap=8&sec=1","verses":[{"n":2,"t":"또한 악귀를 쫓아내심과 병 고침을 받은 어떤 여자들 곧 일곱 귀신이 나간 자 막달라인이라 하는 마리아와"}]},{"ref":"마태복음 28:9","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=mat&chap=28&sec=1","verses":[{"n":9,"t":"예수께서 저희를 만나 가라사대 평안하뇨 하시거늘 여자들이 나아가 그 발을 붙잡고 경배하니"}]}]},"M+T+W":{"intro":"아삽은 하나님의 궤 앞에서 찬양하는 레위 사람들의 우두머리로 제금을 크게 쳤어요. 다윗은 아삽과 그 형제들을 세워 여호와께 감사하게 했어요. 그 노래에는 여호와가 행하신 일을 만민 중에 알리라는 말이 있어요.","main":[{"ref":"역대상 16:5","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=1ch&chap=16&sec=1","verses":[{"n":5,"t":"그 두목은 아삽이요 다음은 스가랴와 여이엘과 스미라못과 여히엘과 맛디디아와 엘리압과 브나야와 오벧에돔과 여이엘이라 비파와 수금을 타고 아삽은 제금을 힘있게 치고"}]},{"ref":"역대상 16:8","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=1ch&chap=16&sec=1","verses":[{"n":8,"t":"너희는 여호와께 감사하며 그 이름을 불러 아뢰며 그 행사를 만민 중에 알게 할찌어다"}]}],"more":[{"ref":"시편 78:1","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=psa&chap=78&sec=1","verses":[{"n":1,"t":"내 백성이여, 내 교훈을 들으며 내 입의 말에 귀를 기울일찌어다"}]},{"ref":"역대상 16:24","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=1ch&chap=16&sec=1","verses":[{"n":24,"t":"그 영광을 열방 중에, 그 기이한 행적을 만민 중에 선포할찌어다"}]},{"ref":"시편 78:2-4","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=psa&chap=78&sec=1","verses":[{"n":2,"t":"내가 입을 열고 비유를 베풀어서 옛 비밀한 말을 발표하리니"},{"n":3,"t":"이는 우리가 들은 바요 아는 바요 우리 열조가 우리에게 전한 바라"},{"n":4,"t":"우리가 이를 그 자손에게 숨기지 아니하고 여호와의 영예와 그 능력과 기이한 사적을 후대에 전하리로다"}]},{"ref":"역대상 16:7","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=1ch&chap=16&sec=1","verses":[{"n":7,"t":"그 날에 다윗이 아삽과 그 형제를 세워 위선 여호와께 감사하게 하여 이르기를"}]}]},"P+R+S":{"intro":"아브라함은 집안의 모든 일을 맡아보던 늙은 종을 불러 아들의 아내를 구하러 가도록 일렀어요. 종은 주인의 낙타 열 마리와 좋은 것들을 가지고 떠났어요. 그 길에서 종은 아브라함의 하나님께 순조롭게 인도해 달라고 간구했어요.","main":[{"ref":"창세기 24:2","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=gen&chap=24&sec=1","verses":[{"n":2,"t":"아브라함이 자기 집 모든 소유를 맡은 늙은 종에게 이르되 청컨대 네 손을 내 환도뼈 밑에 넣으라"}]},{"ref":"창세기 24:10","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=gen&chap=24&sec=1","verses":[{"n":10,"t":"이에 종이 그 주인의 약대 중 열 필을 취하고 떠났는데 곧 그 주인의 모든 좋은 것을 가지고 떠나 메소보다미아로 가서 나홀의 성에 이르러"}]}],"more":[{"ref":"창세기 24:12","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=gen&chap=24&sec=1","verses":[{"n":12,"t":"그가 가로되 우리 주인 아브라함의 하나님 여호와여 원컨대 오늘날 나로 순적히 만나게 하사 나의 주인 아브라함에게 은혜를 베푸시옵소서"}]},{"ref":"창세기 24:13-14","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=gen&chap=24&sec=1","verses":[{"n":13,"t":"성중 사람의 딸들이 물 길러 나오겠사오니 내가 우물 곁에 섰다가"},{"n":14,"t":"한 소녀에게 이르기를 청컨대 너는 물 항아리를 기울여 나로 마시게 하라 하리니 그의 대답이 마시라 내가 당신의 약대에게도 마시우리라 하면 그는 주께서 주의 종 이삭을 위하여 정하신 자라 이로 인하여 주께서 나의 주인에게 은혜 베푸심을 내가 알겠나이다"}]}]},"P+R+T":{"intro":"다니엘은 왕의 음식으로 자기를 더럽히지 않으려고 열흘 동안 채식으로 시험해 보자고 했어요. 하나님은 그와 친구들에게 학문과 지혜를 주셨어요. 왕의 꿈 때문에 죽게 되었을 때에는 친구들과 함께 기도했어요.","main":[{"ref":"다니엘 1:8","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=dan&chap=1&sec=1","verses":[{"n":8,"t":"다니엘은 뜻을 정하여 왕의 진미와 그의 마시는 포도주로 자기를 더럽히지 아니하리라 하고 자기를 더럽히지 않게 하기를 환관장에게 구하니"}]},{"ref":"다니엘 2:18","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=dan&chap=2&sec=1","verses":[{"n":18,"t":"하늘에 계신 하나님이 이 은밀한 일에 대하여 긍휼히 여기사 자기 다니엘과 동무들이 바벨론의 다른 박사와 함께 죽임을 당치 않게 하시기를 그들로 구하게 하니라"}]}],"more":[{"ref":"다니엘 2:17","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=dan&chap=2&sec=1","verses":[{"n":17,"t":"이에 다니엘이 자기 집으로 돌아가서 그 동무 하나냐와 미사엘과 아사랴에게 그 일을 고하고"}]},{"ref":"다니엘 1:12","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=dan&chap=1&sec=1","verses":[{"n":12,"t":"청하오니 당신의 종들을 열흘 동안 시험하여 채식을 주어 먹게 하고 물을 주어 마시게 한 후에"}]},{"ref":"다니엘 1:13","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=dan&chap=1&sec=1","verses":[{"n":13,"t":"당신 앞에서 우리의 얼굴과 왕의 진미를 먹는 소년들의 얼굴을 비교하여 보아서 보이는대로 종들에게 처분하소서 하매"}]},{"ref":"다니엘 1:17","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=dan&chap=1&sec=1","verses":[{"n":17,"t":"하나님이 이 네 소년에게 지식을 얻게 하시며 모든 학문과 재주에 명철하게 하신 외에 다니엘은 또 모든 이상과 몽조를 깨달아 알더라"}]},{"ref":"다니엘 2:24","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=dan&chap=2&sec=1","verses":[{"n":24,"t":"이에 다니엘이 왕이 바벨론 박사들을 멸하라 명한 아리옥에게로 가서 이르매 그에게 이같이 이르되 바벨론 박사들을 멸하지 말고 나를 왕의 앞으로 인도하라 그리하면 내가 그 해석을 왕께 보여 드리리라"}]}]},"P+R+W":{"intro":"큰 무리가 쳐들어오자 여호사밧은 회중 가운데 서서 어떻게 할 줄 모르고 오직 주만 바라본다고 기도했어요. 응답을 들은 뒤에는 얼굴을 땅에 대고 경배했어요. 백성과 의논해 노래하는 사람들을 군대 앞에 세워 여호와께 감사하게 했어요.","main":[{"ref":"역대하 20:12","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=2ch&chap=20&sec=1","verses":[{"n":12,"t":"우리 하나님이여 저희를 징벌하지 아니하시나이까 우리를 치러 오는 이 큰 무리를 우리가 대적할 능력이 없고 어떻게 할줄도 알지 못하옵고 오직 주만 바라보나이다 하고"}]},{"ref":"역대하 20:21","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=2ch&chap=20&sec=1","verses":[{"n":21,"t":"백성으로 더불어 의논하고 노래하는 자를 택하여 거룩한 예복을 입히고 군대 앞에서 행하며 여호와를 찬송하여 이르기를 여호와께 감사하세 그 자비하심이 영원하도다 하게 하였더니"}]}],"more":[{"ref":"역대하 20:5","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=2ch&chap=20&sec=1","verses":[{"n":5,"t":"여호사밧이 여호와의 전 새 뜰 앞에서 유다와 예루살렘의 회중 가운데 서서"}]},{"ref":"역대하 20:6-11","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=2ch&chap=20&sec=1","verses":[{"n":6,"t":"가로되 우리 열조의 하나님 여호와여 주는 하늘에서 하나님이 아니시니이까 이방 사람의 모든 나라를 다스리지 아니하시나이까 주의 손에 권세와 능력이 있사오니 능히 막을 사람이 없나이다"},{"n":7,"t":"우리 하나님이시여 전에 이 땅 거민을 주의 백성 이스라엘 앞에서 쫓아내시고 그 땅으로 주의 벗 아브라함의 자손에게 영영히 주지 아니하셨나이까"},{"n":8,"t":"저희가 이 땅에 거하여 주의 이름을 위하여 한 성소를 건축하고 이르기를"},{"n":9,"t":"만일 재앙이나 난리나 견책이나 온역이나 기근이 우리에게 임하면 주의 이름이 이 전에 있으니 우리가 이 전 앞과 주의 앞에 서서 이 환난 가운데서 주께 부르짖은즉 들으시고 구원하시리라 하였나이다"},{"n":10,"t":"옛적에 이스라엘이 애굽 땅에서 나올 때에 암몬 자손과 모압 자손과 세일산 사람을 침노하기를 주께서 용납하지 아니하시므로 이에 치우쳐 저희를 떠나고 멸하지 아니하였거늘"},{"n":11,"t":"이제 저희가 우리에게 갚는 것을 보옵소서 저희가 와서 주께서 우리에게 주신 주의 기업에서 우리를 쫓아 내고자 하나이다"}]},{"ref":"역대하 20:18","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=2ch&chap=20&sec=1","verses":[{"n":18,"t":"여호사밧이 몸을 굽혀 얼굴을 땅에 대니 온 유다와 예루살렘 거민들도 여호와 앞에 엎드려 경배하고"}]}]},"P+S+T":{"intro":"스데반은 구제를 맡을 일곱 사람 가운데 한 사람으로 뽑혔어요. 지혜와 성령으로 말하여 논쟁하던 사람들이 그를 당하지 못했고, 공회 앞에서 이스라엘의 역사를 풀어 말했어요. 돌에 맞으면서 주여 이 죄를 그들에게 돌리지 마옵소서 하고 기도했어요.","main":[{"ref":"사도행전 6:5","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=act&chap=6&sec=1","verses":[{"n":5,"t":"온 무리가 이 말을 기뻐하여 믿음과 성령이 충만한 사람 스데반과 또 빌립과 브로고로와 니가노르와 디몬과 바메나와 유대교에 입교한 안디옥 사람 니골라를 택하여"}]},{"ref":"사도행전 7:60","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=act&chap=7&sec=1","verses":[{"n":60,"t":"무릎을 꿇고 크게 불러 가로되 주여 이 죄를 저들에게 돌리지 마옵소서 이 말을 하고 자니라"}]}],"more":[{"ref":"사도행전 7:59","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=act&chap=7&sec=1","verses":[{"n":59,"t":"저희가 돌로 스데반을 치니 스데반이 부르짖어 가로되 주 예수여 내 영혼을 받으시옵소서 하고"}]},{"ref":"사도행전 6:10","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=act&chap=6&sec=1","verses":[{"n":10,"t":"스데반이 지혜와 성령으로 말함을 저희가 능히 당치 못하여"}]},{"ref":"사도행전 6:2-4","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=act&chap=6&sec=1","verses":[{"n":2,"t":"열 두 사도가 모든 제자를 불러 이르되 우리가 하나님의 말씀을 제쳐 놓고 공궤를 일삼는 것이 마땅치 아니하니"},{"n":3,"t":"형제들아 너희 가운데서 성령과 지혜가 충만하여 칭찬 듣는 사람 일곱을 택하라 우리가 이 일을 저희에게 맡기고"},{"n":4,"t":"우리는 기도하는 것과 말씀 전하는 것을 전무하리라 하니"}]},{"ref":"사도행전 7:2","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=act&chap=7&sec=1","verses":[{"n":2,"t":"스데반이 가로되 여러분 부형들이여 들으소서 우리 조상 아브라함이 하란에 있기 전 메소보다미아에 있을 때에 영광의 하나님이 그에게 보여"}]}]},"P+S+W":{"intro":"제사장 사가랴는 자기 반열의 차례가 되자 성전에 들어가 분향하는 직무를 했어요. 천사는 그의 간구가 들렸다고 말했어요. 말을 못하게 되었다가 아들의 이름을 요한이라 쓰자 입이 열려 하나님을 찬송했어요.","main":[{"ref":"누가복음 1:9","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=luk&chap=1&sec=1","verses":[{"n":9,"t":"제사장의 전례를 따라 제비를 뽑아 주의 성소에 들어가 분향하고"}]},{"ref":"누가복음 1:64","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=luk&chap=1&sec=1","verses":[{"n":64,"t":"이에 그 입이 곧 열리고 혀가 풀리며 말을 하여 하나님을 찬송하니"}]}],"more":[{"ref":"누가복음 1:8","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=luk&chap=1&sec=1","verses":[{"n":8,"t":"마침 사가랴가 그 반열의 차례대로 제사장의 직무를 하나님 앞에 행할쌔"}]},{"ref":"누가복음 1:13","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=luk&chap=1&sec=1","verses":[{"n":13,"t":"천사가 일러 가로되 사가랴여 무서워 말라 너의 간구함이 들린지라 네 아내 엘리사벳이 네게 아들을 낳아 주리니 그 이름을 요한이라 하라"}]}]},"P+T+W":{"intro":"에스라는 여호와의 율법을 연구하여 지키고 이스라엘에게 가르치기로 마음을 정했어요. 백성의 죄를 듣고 저녁 제사 때 무릎을 꿇고 손을 들어 기도했어요. 율법책을 펼 때 그가 여호와를 송축하자 모든 백성이 아멘 하고 엎드려 경배했어요.","main":[{"ref":"에스라 7:10","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=ezr&chap=7&sec=1","verses":[{"n":10,"t":"에스라가 여호와의 율법을 연구하여 준행하며 율례와 규례를 이스라엘에게 가르치기로 결심하였었더라"}]},{"ref":"에스라 9:5","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=ezr&chap=9&sec=1","verses":[{"n":5,"t":"저녁 제사를 드릴 때에 내가 근심 중에 일어나서 속옷과 겉옷을 찢은대로 무릎을 꿇고 나의 하나님 여호와를 향하여 손을 들고"}]}],"more":[{"ref":"에스라 9:6","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=ezr&chap=9&sec=1","verses":[{"n":6,"t":"말하기를 나의 하나님이여 내가 부끄러워 낯이 뜨뜻하여 감히 나의 하나님을 향하여 얼굴을 들지 못하오니 이는 우리 죄악이 많아 정수리에 넘치고 우리 허물이 커서 하늘에 미침이니이다"}]},{"ref":"느헤미야 8:6","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=neh&chap=8&sec=1","verses":[{"n":6,"t":"에스라가 광대하신 하나님 여호와를 송축하매 모든 백성이 손을 들고 아멘 아멘 응답하고 몸을 굽혀 얼굴을 땅에 대고 여호와께 경배하였느니라"}]}]},"R+S+T":{"intro":"하나님은 브살렐에게 지혜와 총명과 지식을 주어 금과 은과 놋으로 만드는 기술을 고안하게 하셨어요. 그와 오홀리압의 마음을 감동시켜 가르치게도 하셨어요. 브살렐은 조각목으로 언약궤를 만들었어요.","main":[{"ref":"출애굽기 35:34","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=exo&chap=35&sec=1","verses":[{"n":34,"t":"또 그와 단 지파 아히사막의 아들 오홀리압을 감동시키사 가르치게 하시며"}]},{"ref":"출애굽기 37:1","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=exo&chap=37&sec=1","verses":[{"n":1,"t":"브살렐이 조각목으로 궤를 만들었으니 장이 이 규빗 반, 광이 일 규빗 반, 고가 일 규빗 반이며"}]}],"more":[{"ref":"출애굽기 35:31","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=exo&chap=35&sec=1","verses":[{"n":31,"t":"하나님의 신을 그에게 충만케 하여 지혜와 총명과 지식으로 여러가지 일을 하게 하시되"}]},{"ref":"출애굽기 35:32-33","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=exo&chap=35&sec=1","verses":[{"n":32,"t":"공교한 일을 연구하여 금과 은과 놋으로 일하게 하시며"},{"n":33,"t":"보석을 깎아 물리며 나무를 새기는 여러가지 공교한 일을 하게 하셨고"}]}]},"R+S+W":{"intro":"오홀리압은 브살렐과 함께 정교한 일을 고안하는 지혜를 받았어요. 그는 조각하고, 청색·자색·홍색 실과 가는 베 실로 수를 놓는 사람이었어요. 모세가 그들을 불러 성소의 모든 일을 하게 했어요.","main":[{"ref":"출애굽기 35:35","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=exo&chap=35&sec=1","verses":[{"n":35,"t":"지혜로운 마음을 그들에게 충만하게 하사 여러가지 일을 하게 하시되 조각하는 일과 공교로운 일과 청색 자색 홍색실과 가는 베실로 수 놓는 일과 짜는 일과 그 외에 여러가지 일을 하게 하시고 공교로운 일을 연구하게 하셨나니"}]},{"ref":"출애굽기 38:23","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=exo&chap=38&sec=1","verses":[{"n":23,"t":"단 지파 아히사막의 아들 오홀리압은 그와 함께 하였으니 오홀리압은 재능이 있어서 조각하며 또 청색 자색 홍색실과 가는 베실로 수 놓은 자더라"}]}],"more":[{"ref":"출애굽기 36:1","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=exo&chap=36&sec=1","verses":[{"n":1,"t":"브살렐과 오홀리압과 및 마음이 지혜로운 사람 곧 여호와께서 지혜와 총명을 부으사 성소에 쓸 모든 일을 할줄 알게 하심을 입은 자들은 여호와의 무릇 명하신대로 할 것이니라"}]},{"ref":"출애굽기 36:2","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=exo&chap=36&sec=1","verses":[{"n":2,"t":"모세가 브살렐과 오홀리압과 및 마음이 지혜로운 사람 곧 그 마음에 여호와께로 지혜를 얻고 와서 그 일을 하려고 마음에 원하는 모든 자를 부르매"}]}]},"R+T+W":{"intro":"후람은 두로의 놋 장인으로 놋 기구를 만드는 지혜와 총명과 기술을 가진 사람이었어요. 솔로몬 왕이 그를 불러 성전의 놋 기구를 모두 만들게 했어요. 그가 만든 기구들은 성전에서 쓰였어요.","main":[{"ref":"열왕기상 7:14","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=1ki&chap=7&sec=1","verses":[{"n":14,"t":"저는 납달리 지파 과부의 아들이요 그 아비는 두로 사람이니 놋점장이라 이 히람은 모든 놋 일에 지혜와 총명과 재능이 구비한 자더니 솔로몬왕에게 와서 그 모든 공작을 하니라"}]},{"ref":"열왕기상 7:40","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=1ki&chap=7&sec=1","verses":[{"n":40,"t":"히람이 또 물두멍과 부삽과 대접들을 만들었더라 이와 같이 히람이 솔로몬왕을 위하여 여호와의 전의 모든 일을 마쳤으니"}]}],"more":[{"ref":"열왕기상 7:13","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=1ki&chap=7&sec=1","verses":[{"n":13,"t":"솔로몬왕이 보내어 히람을 두로에서 데려오니"}]},{"ref":"열왕기상 7:41-45","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=1ki&chap=7&sec=1","verses":[{"n":41,"t":"곧 기둥 둘과 그 기둥 꼭대기의 공 같은 머리 둘과 또 기둥 꼭대기의 공 같은 머리를 가리우는 그물 둘과"},{"n":42,"t":"또 그 그물들을 위하여 만든바 매 그물에 두줄씩으로 기둥 위의 공 같은 두 머리를 가리우게 한 사백 석류와"},{"n":43,"t":"또 열 받침과 받침 위의 열 물두멍과"},{"n":44,"t":"한 바다와 그 바다 아래 열 두 소와"},{"n":45,"t":"솥과 부삽과 대접들이라 히람이 솔로몬왕을 위하여 여호와의 전에 이 모든 그릇을 빛난 놋으로 만드니라"}]},{"ref":"역대하 4:11","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=2ch&chap=4&sec=1","verses":[{"n":11,"t":"후람이 또 솥과 부삽과 대접을 만들었더라 이와 같이 후람이 솔로몬왕을 위하여 하나님의 전에서 하는 일을 마쳤으니"}]},{"ref":"역대하 4:16","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=2ch&chap=4&sec=1","verses":[{"n":16,"t":"솥과 부삽과 고기 갈고리와 여호와의 전의 모든 그릇들이라 후람의 아비가 솔로몬왕을 위하여 빛난 놋으로 만들 때에"}]}]},"S+T+W":{"intro":"헤만은 하나님의 말씀을 받드는 왕의 선견자로 기록되어 있어요. 그의 아들들은 아버지의 지휘 아래 제금과 비파와 수금으로 하나님의 전에서 노래하며 섬겼어요. 헤만도 아삽과 여두둔과 함께 왕의 지휘를 받았어요.","main":[{"ref":"역대상 25:5","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=1ch&chap=25&sec=1","verses":[{"n":5,"t":"이는 다 헤만의 아들들이니 나팔을 부는 자며 헤만은 하나님의 말씀을 받드는 왕의 선견자라 하나님이 헤만에게 열 네 아들과 세 딸을 주셨더라"}]},{"ref":"역대상 25:6","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=1ch&chap=25&sec=1","verses":[{"n":6,"t":"이들이 다 그 아비의 수하에 속하여 제금과 비파와 수금을 잡아 여호와 하나님의 전에서 노래하여 섬겼으며 아삽과 여두둔과 헤만은 왕의 수하에 속하였으니"}]}],"more":[{"ref":"역대상 25:1","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=1ch&chap=25&sec=1","verses":[{"n":1,"t":"다윗이 군대 장관들로 더불어 아삽과 헤만과 여두둔의 자손 중에서 구별하여 섬기게 하되 수금과 비파와 제금을 잡아 신령한 노래를 하게 하였으니 그 직무대로 일하는 자의 수효가 이러하니라"}]},{"ref":"역대상 25:7","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=1ch&chap=25&sec=1","verses":[{"n":7,"t":"저희와 모든 형제 곧 여호와 찬송하기를 배워 익숙한 자의 수효가 이백 팔십 팔인이라"}]},{"ref":"역대상 25:8","url":"https://www.bskorea.or.kr/bible/korbibReadpage.php?version=HAN&book=1ch&chap=25&sec=1","verses":[{"n":8,"t":"이 무리의 큰 자나 작은 자나 스승이나 제자를 무론하고 일례로 제비 뽑아 직임을 얻었으니"}]}]}}};
